import { InjectionToken } from '@angular/core';

export interface MidiDeviceInfo {
  id: string;
  name: string;
  is_connected: boolean;
}

export interface MidiChord {
  notes: number[];
  hand: string;
  velocity: number;
  timestamp_ms: number;
}

export interface LessonMetadata {
  id: string;
  title: string;
  description?: string;
  mode: LessonMode;
  duration_seconds: number;
}

export interface Lesson {
  title: string;
  description?: string;
  mode: LessonMode;
  tempo: number;
  time_signature: string;
  key_signature: string;
  total_beats: number;
  total_seconds: number;
  measures: Measure[];
}

export interface Measure {
  number: number;
  notes: Note[];
}

export type Note = SingleNote | ChordNote | RestNote;

export interface SingleNote {
  midi: number;
  duration: number;
  hand: string;
  accidental?: string;
}

export interface ChordNote {
  midi: number[];
  duration: number;
  hand: string;
  chord?: string;
}

export interface RestNote {
  duration: number;
}

export type LessonMode =
  | 'study_left_hand_no_timing'
  | 'study_right_hand_no_timing'
  | 'study_two_hands_no_timing'
  | 'play_left_hand_timing'
  | 'play_right_hand_timing'
  | 'play_two_hands_timing';

/**
 * Backend Client Interface
 * All backend communication should go through this interface
 */
export interface BackendClient {
  // MIDI Commands
  listMidiDevices(): Promise<MidiDeviceInfo[]>;
  startMidiListening(deviceId: string): Promise<void>;
  stopMidiListening(): Promise<void>;
  isMidiConnected(): Promise<boolean>;

  // Lesson Commands
  listLessons(): Promise<LessonMetadata[]>;
  loadLesson(lessonId: string): Promise<Lesson>;

  // Event Listeners (returns cleanup function)
  onMidiChordDetected(callback: (chord: MidiChord) => void): () => void;
  onMidiNoteOff(callback: (midi: number) => void): () => void;
}

/**
 * Injection Token for BackendClient
 * Use this token for dependency injection instead of the interface
 */
export const BACKEND_CLIENT = new InjectionToken<BackendClient>('BackendClient');

/**
 * Backend Client Error
 * Standardized error type for backend operations
 */
export class BackendClientError extends Error {
  constructor(
    message: string,
    public code?: string,
    public details?: unknown
  ) {
    super(message);
    this.name = 'BackendClientError';
  }
}

export * from './backend-client.interface';
export { TauriBackendClient } from './tauri-backend-client';
export { MockBackendClient } from './mock-backend-client';

import { BackendClient, BACKEND_CLIENT } from './backend-client.interface';
import { TauriBackendClient } from './tauri-backend-client';
import { MockBackendClient } from './mock-backend-client';

/**
 * Environment type for client selection
 */
export type BackendEnvironment = 'production' | 'development' | 'test' | 'mock';

/**
 * Configuration for creating a backend client
 */
export interface BackendClientConfig {
  environment?: BackendEnvironment;
  useMock?: boolean;
}

/**
 * Create the appropriate backend client based on environment
 *
 * @param config - Configuration options
 * @returns BackendClient instance
 *
 * @example
 * // Production (default)
 * const client = createBackendClient();
 *
 * @example
 * // Force mock for testing
 * const client = createBackendClient({ useMock: true });
 *
 * @example
 * // Automatic detection
 * const client = createBackendClient({ environment: 'test' });
 */
export function createBackendClient(
  config: BackendClientConfig = {}
): BackendClient {
  const { environment = 'production', useMock = false } = config;

  // Force mock if explicitly requested
  if (useMock) {
    return new MockBackendClient();
  }

  // Use mock in test environment
  if (environment === 'test' || environment === 'mock') {
    return new MockBackendClient();
  }

  // Use Tauri client in production and development
  return new TauriBackendClient();
}

/**
 * Singleton instance for convenience
 * Can be overridden using setDefaultBackendClient()
 */
let defaultClient: BackendClient | null = null;

/**
 * Get the default backend client instance
 * Creates one if it doesn't exist
 */
export function getBackendClient(): BackendClient {
  if (!defaultClient) {
    defaultClient = createBackendClient();
  }
  return defaultClient;
}

/**
 * Set a custom default backend client
 * Useful for testing or custom implementations
 */
export function setDefaultBackendClient(client: BackendClient): void {
  defaultClient = client;
}

/**
 * Reset the default client (useful for test cleanup)
 */
export function resetDefaultBackendClient(): void {
  defaultClient = null;
}

export type NoteState = 'upcoming' | 'active' | 'hit' | 'missed';

/**
 * Timing feedback for note performance
 * - perfect: Hit within the timing window
 * - early: Pressed before the note should have started
 * - late: Started playing after the note should have started
 * - early_release: Released the key before the note duration ended
 * - replayed: Released and pressed again during the same note
 */
export type TimingFeedback = 'perfect' | 'early' | 'late' | 'early_release' | 'replayed' | null;

/**
 * Represents a note or chord in the scrolling player
 */
export interface ScrollingNote {
    /** MIDI note numbers (single note = 1 element, chord = multiple) */
    midi: number[];
    /** Start position in beats from beginning of lesson */
    startBeat: number;
    /** Duration in beats */
    durationBeats: number;
    /** Current rendering/evaluation state */
    state: NoteState;
    /** Which hand plays this note */
    hand: 'left' | 'right';
    /** Whether this is a rest (no sound) */
    isRest: boolean;
    /** Timing feedback (null = not evaluated yet) */
    timingFeedback?: TimingFeedback;
    /** Beat position when the note was actually hit (for late detection) */
    hitBeat?: number;
    /** Whether the note was released early (before duration ended) */
    releasedEarly?: boolean;
    /** Whether the note was replayed after release */
    wasReplayed?: boolean;
}

/**
 * State for a single piano key
 */
export interface KeyState {
    isHint: boolean;
    isActive: boolean;
    isCorrect: boolean;
    isWrong: boolean;
}

/**
 * Visible key data for rendering the virtual keyboard
 */
export interface VisibleKey {
    midi: number;
    isBlack: boolean;
    label: string;
    x: number;
    width: number;
    isHint: boolean;
    isActive: boolean;
    isCorrect: boolean;
    isWrong: boolean;
    isTonic: boolean; // Highlight as the root/home note
}

/**
 * Keyboard range in MIDI note numbers
 */
export interface KeyboardRange {
    min: number;
    max: number;
}

/**
 * Event tracking a wrong note played during the lesson
 */
export interface WrongNoteEvent {
    /** MIDI note that was played incorrectly */
    midi: number;
    /** Beat position when the wrong note was played */
    beat: number;
    /** Timestamp when the wrong note was played (for fade-out) */
    timestamp: number;
}

/**
 * A group of notes that should be beamed together
 * Only for notes with duration < 1 beat (8th, 16th, etc.)
 */
export interface BeamGroup {
    /** Notes in the beam group (ordered by start beat) */
    notes: ScrollingNote[];
    /** Common stem direction for the group (true = up, false = down) */
    stemUp: boolean;
    /** X positions for each note in the group */
    xPositions: number[];
    /** Y positions (average midi Y) for each note */
    yPositions: number[];
    /** Number of beam lines (1 = 8th, 2 = 16th, 3 = 32nd) */
    beamCount: number;
}

/**
 * Key signature information parsed from lesson settings
 */
export interface KeySignature {
    /** Root note name (C, G, F, etc.) */
    root: string;
    /** Mode (major or minor) */
    mode: 'major' | 'minor';
    /** Number of sharps (positive) or flats (negative) */
    accidentals: number;
    /** Which notes are sharped (MIDI note % 12 values) */
    sharpNotes: number[];
    /** Which notes are flatted (MIDI note % 12 values) */
    flatNotes: number[];
}

