  standalone: true,
  imports: [CommonModule],
  template: `
    <canvas #particleCanvas
            class="particle-canvas"
            [width]="canvasWidth"
            [height]="canvasHeight">
    </canvas>
  `,
  styles: [`
    .particle-canvas {
      position: fixed;
      top: 0;
      left: 0;
      width: 100vw;
      height: 100vh;
      pointer-events: none;
      z-index: 9998;
    }
  `]
})
export class ParticleEffectsComponent implements AfterViewInit, OnDestroy {
  @ViewChild('particleCanvas', { static: false }) canvasRef!: ElementRef<HTMLCanvasElement>;

  private evaluationService = inject(EvaluationService);
  private ctx!: CanvasRenderingContext2D;
  private particles: Particle[] = [];
  private animationFrameId: number = 0;
  private lastResultTimestamp: number = 0;

  canvasWidth = window.innerWidth;
  canvasHeight = window.innerHeight;

  constructor() {
    // Listen for evaluation results using effect
    effect(() => {
      const result = this.evaluationService.lastResult();
      const now = Date.now();

      // Avoid duplicate triggers by checking timestamp
      if (result && result.pitch_correct && now - this.lastResultTimestamp > 100) {
        this.lastResultTimestamp = now;

        const isPerfect = result.score >= 100;
        const streak = this.evaluationService.currentStreak();

        if (isPerfect) {
          this.createPerfectNoteEffect(streak);
        } else {
          this.createGoodNoteEffect();
        }

        // Combo effects for streaks
        if (streak >= 10 && streak % 5 === 0) {
          this.createComboEffect(streak);
        }
      }
    });
  }

  ngAfterViewInit(): void {
    const canvas = this.canvasRef.nativeElement;
    this.ctx = canvas.getContext('2d')!;

    // Start animation loop
    this.animate();

    // Handle window resize
    window.addEventListener('resize', () => {
      this.canvasWidth = window.innerWidth;
      this.canvasHeight = window.innerHeight;
    });
  }

  ngOnDestroy(): void {
    if (this.animationFrameId) {
      cancelAnimationFrame(this.animationFrameId);
    }
  }

  /**
   * Create particles for perfect note hit
   */
  private createPerfectNoteEffect(streak: number): void {
    const centerX = this.canvasWidth / 2;
    const centerY = this.canvasHeight / 2;

    // More particles for higher streaks
    const particleCount = Math.min(20 + streak * 2, 50);

    for (let i = 0; i < particleCount; i++) {
      const angle = (Math.PI * 2 * i) / particleCount;
      const velocity = 3 + Math.random() * 2;

      this.particles.push({
        x: centerX,
        y: centerY,
        vx: Math.cos(angle) * velocity,
        vy: Math.sin(angle) * velocity,
        radius: 3 + Math.random() * 3,
        color: this.getStreakColor(streak),
        alpha: 1,
        life: 1
      });
    }

    // Add sparkles
    for (let i = 0; i < 10; i++) {
      this.particles.push({
        x: centerX + (Math.random() - 0.5) * 100,
        y: centerY + (Math.random() - 0.5) * 100,
        vx: (Math.random() - 0.5) * 2,
        vy: (Math.random() - 0.5) * 2,
        radius: 1 + Math.random() * 2,
        color: '#FFD700',
        alpha: 1,
        life: 1,
        sparkle: true
      });
    }
  }

  /**
   * Create subtle effect for good (but not perfect) notes
   */
  private createGoodNoteEffect(): void {
    const centerX = this.canvasWidth / 2;
    const centerY = this.canvasHeight / 2;

    for (let i = 0; i < 8; i++) {
      const angle = (Math.PI * 2 * i) / 8;
      this.particles.push({
        x: centerX,
        y: centerY,
        vx: Math.cos(angle) * 2,
        vy: Math.sin(angle) * 2,
        radius: 2,
        color: '#4CAF50',
        alpha: 0.6,
        life: 1
      });
    }
  }

  /**
   * Create explosion effect for combo milestones
   */
  private createComboEffect(streak: number): void {
    const centerX = this.canvasWidth / 2;
    const centerY = this.canvasHeight / 2 - 100;

    // Large burst
    for (let i = 0; i < 50; i++) {
      const angle = Math.random() * Math.PI * 2;
      const velocity = 4 + Math.random() * 4;

      this.particles.push({
        x: centerX,
        y: centerY,
        vx: Math.cos(angle) * velocity,
        vy: Math.sin(angle) * velocity,
        radius: 4 + Math.random() * 4,
        color: this.getComboColor(streak),
        alpha: 1,
        life: 1
      });
    }

    // Show combo text
    this.showComboText(streak, centerX, centerY);
  }

  /**
   * Show animated combo text
   */
  private showComboText(streak: number, x: number, y: number): void {
    const text = `${streak} COMBO!`;
    const fontSize = 48;

    const textElement = document.createElement('div');
    textElement.textContent = text;
    textElement.style.position = 'fixed';
    textElement.style.left = `${x}px`;
    textElement.style.top = `${y}px`;
    textElement.style.transform = 'translate(-50%, -50%)';
    textElement.style.fontSize = `${fontSize}px`;
    textElement.style.fontWeight = 'bold';
    textElement.style.color = '#FFD700';
    textElement.style.textShadow = '0 0 20px rgba(255, 215, 0, 0.8), 0 0 40px rgba(255, 215, 0, 0.4)';
    textElement.style.pointerEvents = 'none';
    textElement.style.zIndex = '9999';
    document.body.appendChild(textElement);

    // Animate with GSAP
    gsap.timeline()
      .from(textElement, {
        scale: 0,
        rotation: -180,
        duration: 0.5,
        ease: 'back.out(2)'
      })
      .to(textElement, {
        y: '-=100',
        opacity: 0,
        duration: 1,
        ease: 'power2.in',
        onComplete: () => textElement.remove()
      }, '+=0.5');
  }

  /**
   * Get color based on streak
   */
  private getStreakColor(streak: number): string {
    if (streak >= 25) return '#FF1744'; // Red for fire
    if (streak >= 15) return '#FF6F00'; // Orange
    if (streak >= 10) return '#FFD700'; // Gold
    if (streak >= 5) return '#00E676';  // Green
    return '#4CAF50'; // Light green
  }

  /**
   * Get color for combo effects
   */
  private getComboColor(streak: number): string {
    const colors = ['#FFD700', '#FF6F00', '#FF1744', '#E91E63', '#9C27B0'];
    return colors[Math.floor(Math.random() * colors.length)];
  }

  /**
   * Animation loop
   */
  private animate = (): void => {
    this.ctx.clearRect(0, 0, this.canvasWidth, this.canvasHeight);

    // Update and draw particles
    for (let i = this.particles.length - 1; i >= 0; i--) {
      const p = this.particles[i];

      // Update position
      p.x += p.vx;
      p.y += p.vy;
      p.vy += 0.1; // Gravity

      // Update life
      p.life -= 0.02;
      p.alpha = p.life;

      // Remove dead particles
      if (p.life <= 0) {
        this.particles.splice(i, 1);
        continue;
      }

      // Draw particle
      this.ctx.globalAlpha = p.alpha;
      this.ctx.fillStyle = p.color;
      this.ctx.beginPath();

      if (p.sparkle) {
        // Draw star for sparkles
        this.drawStar(p.x, p.y, p.radius, 5);
      } else {
        // Draw circle for normal particles
        this.ctx.arc(p.x, p.y, p.radius, 0, Math.PI * 2);
      }

      this.ctx.fill();
    }

    this.ctx.globalAlpha = 1;
    this.animationFrameId = requestAnimationFrame(this.animate);
  };

  /**
   * Draw a star shape
   */
  private drawStar(cx: number, cy: number, radius: number, points: number): void {
    const step = Math.PI / points;
    this.ctx.beginPath();
    this.ctx.moveTo(cx, cy - radius);

    for (let i = 0; i < points * 2; i++) {
      const r = i % 2 === 0 ? radius : radius / 2;
      const angle = i * step - Math.PI / 2;
      this.ctx.lineTo(cx + r * Math.cos(angle), cy + r * Math.sin(angle));
    }

    this.ctx.closePath();
  }
}

interface Particle {
  x: number;
  y: number;
  vx: number;
  vy: number;
  radius: number;
  color: string;
  alpha: number;
  life: number;
  sparkle?: boolean;
}

import { Injectable, computed, inject, signal } from '@angular/core';
import { LessonDTO, MeasureDTO } from '../models/lesson.model';
import { NoteDTO, isChordNote, isRestNote, isSingleNote, SingleNoteDTO, ChordNoteDTO } from '../models/note.model';
import { PianoSoundService } from './piano-sound.service';

export type PlaybackState = 'stopped' | 'playing' | 'paused';

export interface PlaybackPosition {
  measureIndex: number;
  noteIndex: number;
  timeMs: number;
}

export interface NoteTimingInfo {
  measureIndex: number;
  noteIndex: number;
  startTimeMs: number;
  durationMs: number;
  midiNotes: number[];
  isRest: boolean;
}

/**
 * Playback Service
 * Manages lesson playback with moving cursor and piano sounds
 */
@Injectable({
  providedIn: 'root'
})
export class PlaybackService {
  private pianoSound = inject(PianoSoundService);

  // State
  private readonly _state = signal<PlaybackState>('stopped');
  private readonly _currentPosition = signal<PlaybackPosition>({ measureIndex: 0, noteIndex: 0, timeMs: 0 });
  private readonly _tempo = signal<number>(120); // BPM
  private readonly _lesson = signal<LessonDTO | null>(null);

  // Timing data computed from lesson
  private noteTimings: NoteTimingInfo[] = [];
  private totalDurationMs = 0;

  // Playback control
  private playbackStartTime = 0;
  private pausedAtTime = 0;
  private animationFrameId: number | null = null;

  // Public signals
  readonly state = this._state.asReadonly();
  readonly currentPosition = this._currentPosition.asReadonly();
  readonly tempo = this._tempo.asReadonly();

  // Computed signals
  readonly isPlaying = computed(() => this._state() === 'playing');
  readonly isPaused = computed(() => this._state() === 'paused');
  readonly isStopped = computed(() => this._state() === 'stopped');

  readonly progressPercent = computed(() => {
    if (this.totalDurationMs === 0) return 0;
    return Math.min(100, (this._currentPosition().timeMs / this.totalDurationMs) * 100);
  });

  /**
   * Load a lesson for playback
   */
  loadLesson(lesson: LessonDTO): void {
    this.stop();
    this._lesson.set(lesson);
    this._tempo.set(lesson.tempo);
    this.calculateNoteTimings(lesson);
    console.log('[Playback] Lesson loaded, total duration:', this.totalDurationMs, 'ms');
  }

  /**
   * Calculate timing for each note based on tempo
   */
  private calculateNoteTimings(lesson: LessonDTO): void {
    this.noteTimings = [];
    let currentTimeMs = 0;

    // Calculate milliseconds per beat
    const msPerBeat = (60 / lesson.tempo) * 1000;

    // Parse time signature (e.g., "4/4" -> 4 beats per measure)
    const [beatsPerMeasure] = lesson.time_signature.split('/').map(Number);

    // Calculate beat value (quarter note = 1, half = 2, etc.)
    const beatValue = 4; // Assuming quarter note gets the beat

    lesson.measures.forEach((measure, measureIndex) => {
      measure.notes.forEach((note, noteIndex) => {
        // Duration is already in beats (number)
        const durationBeats = note.duration;
        const durationMs = durationBeats * msPerBeat;

        const timing: NoteTimingInfo = {
          measureIndex,
          noteIndex,
          startTimeMs: currentTimeMs,
          durationMs,
          midiNotes: this.getMidiFromNote(note),
          isRest: isRestNote(note)
        };

        this.noteTimings.push(timing);
        currentTimeMs += durationMs;
      });
    });

    this.totalDurationMs = currentTimeMs;
  }

  /**
   * Get MIDI notes from a note DTO
   */
  private getMidiFromNote(note: NoteDTO): number[] {
    if (isRestNote(note)) return [];
    if (isSingleNote(note)) return [(note as SingleNoteDTO).midi];
    if (isChordNote(note)) return (note as ChordNoteDTO).midi;
    return [];
  }

  /**
   * Start or resume playback
   */
  play(): void {
    if (!this._lesson()) return;

    // Initialize piano sound
    this.pianoSound.initAudio();

    if (this._state() === 'paused') {
      // Resume from paused position
      this.playbackStartTime = performance.now() - this.pausedAtTime;
    } else {
      // Start from beginning
      this.playbackStartTime = performance.now();
      this._currentPosition.set({ measureIndex: 0, noteIndex: 0, timeMs: 0 });
    }

    this._state.set('playing');
    this.startPlaybackLoop();
    console.log('[Playback] Started playback');
  }

  /**
   * Pause playback
   */
  pause(): void {
    if (this._state() !== 'playing') return;

    this._state.set('paused');
    this.pausedAtTime = this._currentPosition().timeMs;
    this.stopPlaybackLoop();
    this.pianoSound.stopAll();
    console.log('[Playback] Paused at', this.pausedAtTime, 'ms');
  }

  /**
   * Stop playback and reset to beginning
   */
  stop(): void {
    this._state.set('stopped');
    this.stopPlaybackLoop();
    this.pianoSound.stopAll();
    this._currentPosition.set({ measureIndex: 0, noteIndex: 0, timeMs: 0 });
    this.pausedAtTime = 0;
    console.log('[Playback] Stopped');
  }

  /**
   * Toggle play/pause
   */
  toggle(): void {
    if (this._state() === 'playing') {
      this.pause();
    } else {
      this.play();
    }
  }

  /**
   * Seek to a specific position (by percentage)
   */
  seekTo(percent: number): void {
    const wasPlaying = this._state() === 'playing';
    if (wasPlaying) {
      this.pause();
    }

    const targetTime = (percent / 100) * this.totalDurationMs;
    this.pausedAtTime = targetTime;

    // Find the note at this time
    const noteIndex = this.noteTimings.findIndex(
      (timing, i) => timing.startTimeMs <= targetTime &&
        (i === this.noteTimings.length - 1 || this.noteTimings[i + 1].startTimeMs > targetTime)
    );

    if (noteIndex >= 0) {
      const timing = this.noteTimings[noteIndex];
      this._currentPosition.set({
        measureIndex: timing.measureIndex,
        noteIndex: timing.noteIndex,
        timeMs: targetTime
      });
    }

    if (wasPlaying) {
      this.play();
    }
  }

  /**
   * Set playback tempo
   */
  setTempo(bpm: number): void {
    const lesson = this._lesson();
    if (!lesson) return;

    const wasPlaying = this._state() === 'playing';
    const currentProgress = this.progressPercent();

    if (wasPlaying) {
      this.pause();
    }

    this._tempo.set(bpm);
    // Recalculate timings with new tempo
    this.calculateNoteTimings({ ...lesson, tempo: bpm });

    // Seek to equivalent position
    if (currentProgress > 0) {
      this.seekTo(currentProgress);
    }

    if (wasPlaying) {
      this.play();
    }
  }

  /**
   * Main playback loop
   */
  private startPlaybackLoop(): void {
    let lastNoteIndex = -1;

    const tick = () => {
      if (this._state() !== 'playing') return;

      const currentTimeMs = performance.now() - this.playbackStartTime;

      // Find current note
      const noteIndex = this.noteTimings.findIndex(
        (timing, i) => timing.startTimeMs <= currentTimeMs &&
          (i === this.noteTimings.length - 1 || this.noteTimings[i + 1].startTimeMs > currentTimeMs)
      );

      // Check if we moved to a new note
      if (noteIndex >= 0 && noteIndex !== lastNoteIndex) {
        const timing = this.noteTimings[noteIndex];

        // Update position
        this._currentPosition.set({
          measureIndex: timing.measureIndex,
          noteIndex: timing.noteIndex,
          timeMs: currentTimeMs
        });

        // Play the note if not a rest
        if (!timing.isRest && timing.midiNotes.length > 0) {
          // Stop previous notes
          this.pianoSound.stopAll();

          // Play new notes
          timing.midiNotes.forEach(midi => {
            this.pianoSound.playNote(midi, 100);
          });

          // Schedule note off
          setTimeout(() => {
            timing.midiNotes.forEach(midi => {
              this.pianoSound.stopNote(midi);
            });
          }, timing.durationMs * 0.9); // Release slightly before next note
        }

        lastNoteIndex = noteIndex;
      }

      // Check if playback is complete
      if (currentTimeMs >= this.totalDurationMs) {
        console.log('[Playback] Playback complete');
        this.stop();
        return;
      }

      // Update time position
      this._currentPosition.update(pos => ({ ...pos, timeMs: currentTimeMs }));

      this.animationFrameId = requestAnimationFrame(tick);
    };

    this.animationFrameId = requestAnimationFrame(tick);
  }

  /**
   * Stop the playback loop
   */
  private stopPlaybackLoop(): void {
    if (this.animationFrameId !== null) {
      cancelAnimationFrame(this.animationFrameId);
      this.animationFrameId = null;
    }
  }

  /**
   * Get total duration in formatted string
   */
  get totalDurationFormatted(): string {
    const totalSeconds = Math.floor(this.totalDurationMs / 1000);
    const minutes = Math.floor(totalSeconds / 60);
    const seconds = totalSeconds % 60;
    return `${minutes}:${seconds.toString().padStart(2, '0')}`;
  }

  /**
   * Get current time in formatted string
   */
  get currentTimeFormatted(): string {
    const currentSeconds = Math.floor(this._currentPosition().timeMs / 1000);
    const minutes = Math.floor(currentSeconds / 60);
    const seconds = currentSeconds % 60;
    return `${minutes}:${seconds.toString().padStart(2, '0')}`;
  }
}

import { InjectionToken } from '@angular/core';

export interface MidiDeviceInfo {
  id: string;
  name: string;
  is_connected: boolean;
}

export interface MidiChord {
  notes: number[];
  hand: string;
  velocity: number;
  timestamp_ms: number;
}

export interface LessonMetadata {
  id: string;
  title: string;
  description?: string;
  mode: LessonMode;
  duration_seconds: number;
}

export interface Lesson {
  title: string;
  description?: string;
  mode: LessonMode;
  tempo: number;
  time_signature: string;
  key_signature: string;
  total_beats: number;
  total_seconds: number;
  measures: Measure[];
}

export interface Measure {
  number: number;
  notes: Note[];
}

export type Note = SingleNote | ChordNote | RestNote;

export interface SingleNote {
  midi: number;
  duration: number;
  hand: string;
  accidental?: string;
}

export interface ChordNote {
  midi: number[];
  duration: number;
  hand: string;
  chord?: string;
}

export interface RestNote {
  duration: number;
}

export type LessonMode =
  | 'study_left_hand_no_timing'
  | 'study_right_hand_no_timing'
  | 'study_two_hands_no_timing'
  | 'play_left_hand_timing'
  | 'play_right_hand_timing'
  | 'play_two_hands_timing';

/**
 * Backend Client Interface
 * All backend communication should go through this interface
 */
export interface BackendClient {
  // MIDI Commands
  listMidiDevices(): Promise<MidiDeviceInfo[]>;
  startMidiListening(deviceId: string): Promise<void>;
  stopMidiListening(): Promise<void>;
  isMidiConnected(): Promise<boolean>;

  // Lesson Commands
  listLessons(): Promise<LessonMetadata[]>;
  loadLesson(lessonId: string): Promise<Lesson>;

  // Event Listeners (returns cleanup function)
  onMidiChordDetected(callback: (chord: MidiChord) => void): () => void;
  onMidiNoteOff(callback: (midi: number) => void): () => void;
}

/**
 * Injection Token for BackendClient
 * Use this token for dependency injection instead of the interface
 */
export const BACKEND_CLIENT = new InjectionToken<BackendClient>('BackendClient');

/**
 * Backend Client Error
 * Standardized error type for backend operations
 */
export class BackendClientError extends Error {
  constructor(
    message: string,
    public code?: string,
    public details?: unknown
  ) {
    super(message);
    this.name = 'BackendClientError';
  }
}

export interface SingleNoteDTO {
    midi: number;
    duration: number;
    hand: string;
    accidental?: string;
}

/**
 * Chord - has `midi` as array of numbers
 */
export interface ChordNoteDTO {
    midi: number[];
    duration: number;
    hand: string;
    chord?: string;
}

/**
 * Rest - only has duration, no midi
 */
export interface RestNoteDTO {
    duration: number;
}

/**
 * Note union type - matches Rust's #[serde(untagged)] NoteDTO enum
 */
export type NoteDTO = SingleNoteDTO | ChordNoteDTO | RestNoteDTO;

/**
 * Type guards for note discrimination
 */
export function isSingleNote(note: NoteDTO): note is SingleNoteDTO {
    const obj = note as unknown as Record<string, unknown>;
    return 'midi' in note && typeof obj['midi'] === 'number' && 'hand' in note;
}

export function isChordNote(note: NoteDTO): note is ChordNoteDTO {
    const obj = note as unknown as Record<string, unknown>;
    return 'midi' in note && Array.isArray(obj['midi']);
}

export function isRestNote(note: NoteDTO): note is RestNoteDTO {
    return !('midi' in note) && 'duration' in note;
}

/**
 * Convert MIDI number to note name (e.g., 60 -> "C4")
 */
export function midiToNoteName(midi: number): string {
    const noteNames = ['C', 'C#', 'D', 'D#', 'E', 'F', 'F#', 'G', 'G#', 'A', 'A#', 'B'];
    const octave = Math.floor(midi / 12) - 1;
    const noteName = noteNames[midi % 12];
    return `${noteName}${octave}`;
}

/**
 * Get all MIDI numbers from a note (works for single notes and chords)
 */
export function getMidiNumbers(note: NoteDTO): number[] {
    if (isSingleNote(note)) {
        return [note.midi];
    }
    if (isChordNote(note)) {
        return note.midi;
    }
    // It's a rest
    return [];
}

export type NoteState = 'upcoming' | 'active' | 'hit' | 'missed';

/**
 * Timing feedback for note performance
 * - perfect: Hit within the timing window
 * - early: Pressed before the note should have started
 * - late: Started playing after the note should have started
 * - early_release: Released the key before the note duration ended
 * - replayed: Released and pressed again during the same note
 */
export type TimingFeedback = 'perfect' | 'early' | 'late' | 'early_release' | 'replayed' | null;

/**
 * Represents a note or chord in the scrolling player
 */
export interface ScrollingNote {
    /** MIDI note numbers (single note = 1 element, chord = multiple) */
    midi: number[];
    /** Start position in beats from beginning of lesson */
    startBeat: number;
    /** Duration in beats */
    durationBeats: number;
    /** Current rendering/evaluation state */
    state: NoteState;
    /** Which hand plays this note */
    hand: 'left' | 'right';
    /** Whether this is a rest (no sound) */
    isRest: boolean;
    /** Timing feedback (null = not evaluated yet) */
    timingFeedback?: TimingFeedback;
    /** Beat position when the note was actually hit (for late detection) */
    hitBeat?: number;
    /** Whether the note was released early (before duration ended) */
    releasedEarly?: boolean;
    /** Whether the note was replayed after release */
    wasReplayed?: boolean;
}

/**
 * State for a single piano key
 */
export interface KeyState {
    isHint: boolean;
    isActive: boolean;
    isCorrect: boolean;
    isWrong: boolean;
}

/**
 * Visible key data for rendering the virtual keyboard
 */
export interface VisibleKey {
    midi: number;
    isBlack: boolean;
    label: string;
    x: number;
    width: number;
    isHint: boolean;
    isActive: boolean;
    isCorrect: boolean;
    isWrong: boolean;
    isTonic: boolean; // Highlight as the root/home note
}

/**
 * Keyboard range in MIDI note numbers
 */
export interface KeyboardRange {
    min: number;
    max: number;
}

/**
 * Event tracking a wrong note played during the lesson
 */
export interface WrongNoteEvent {
    /** MIDI note that was played incorrectly */
    midi: number;
    /** Beat position when the wrong note was played */
    beat: number;
    /** Timestamp when the wrong note was played (for fade-out) */
    timestamp: number;
}

/**
 * A group of notes that should be beamed together
 * Only for notes with duration < 1 beat (8th, 16th, etc.)
 */
export interface BeamGroup {
    /** Notes in the beam group (ordered by start beat) */
    notes: ScrollingNote[];
    /** Common stem direction for the group (true = up, false = down) */
    stemUp: boolean;
    /** X positions for each note in the group */
    xPositions: number[];
    /** Y positions (average midi Y) for each note */
    yPositions: number[];
    /** Number of beam lines (1 = 8th, 2 = 16th, 3 = 32nd) */
    beamCount: number;
}

/**
 * Key signature information parsed from lesson settings
 */
export interface KeySignature {
    /** Root note name (C, G, F, etc.) */
    root: string;
    /** Mode (major or minor) */
    mode: 'major' | 'minor';
    /** Number of sharps (positive) or flats (negative) */
    accidentals: number;
    /** Which notes are sharped (MIDI note % 12 values) */
    sharpNotes: number[];
    /** Which notes are flatted (MIDI note % 12 values) */
    flatNotes: number[];
}

export type FeedbackType = 'Perfect' | 'Good' | 'Close' | 'Wrong';

/**
 * Evaluation result from check_note command
 * Matches EvaluationResult struct in Rust
 */
export interface EvaluationResult {
    pitch_correct: boolean;
    timing_correct: boolean;
    duration_correct: boolean;
    feedback: FeedbackType;
    score: number;
    message: string;
    timing_offset_ms: number;
    duration_diff_percent: number;
}

/**
 * Session statistics from get_stats command
 * Matches SessionStats struct in Rust
 */
export interface SessionStats {
    total_notes: number;
    correct_notes: number;
    perfect_notes: number;
    current_streak: number;
    best_streak: number;
    accuracy: number;
    average_score: number;
}

/**
 * Helper functions for feedback types
 */
export const FeedbackHelper = {
    /**
     * Get CSS color class for feedback type
     */
    getColor(feedback: FeedbackType): string {
        switch (feedback) {
            case 'Perfect':
            case 'Good':
                return 'green';
            case 'Close':
                return 'yellow';
            case 'Wrong':
                return 'red';
        }
    },

    /**
     * Get Material icon for feedback type
     */
    getIcon(feedback: FeedbackType): string {
        switch (feedback) {
            case 'Perfect':
                return 'star';
            case 'Good':
                return 'check_circle';
            case 'Close':
                return 'help_outline';
            case 'Wrong':
                return 'cancel';
        }
    },

    /**
     * Check if feedback is positive (correct pitch)
     */
    isPositive(feedback: FeedbackType): boolean {
        return feedback === 'Perfect' || feedback === 'Good' || feedback === 'Close';
    }
};

import { InjectionToken } from '@angular/core';

export interface MidiDeviceInfo {
  id: string;
  name: string;
  is_connected: boolean;
}

export interface MidiChord {
  notes: number[];
  hand: string;
  velocity: number;
  timestamp_ms: number;
}

export interface LessonMetadata {
  id: string;
  title: string;
  description?: string;
  mode: LessonMode;
  duration_seconds: number;
}

export interface Lesson {
  title: string;
  description?: string;
  mode: LessonMode;
  tempo: number;
  time_signature: string;
  key_signature: string;
  total_beats: number;
  total_seconds: number;
  measures: Measure[];
}

export interface Measure {
  number: number;
  notes: Note[];
}

export type Note = SingleNote | ChordNote | RestNote;

export interface SingleNote {
  midi: number;
  duration: number;
  hand: string;
  accidental?: string;
}

export interface ChordNote {
  midi: number[];
  duration: number;
  hand: string;
  chord?: string;
}

export interface RestNote {
  duration: number;
}

export type LessonMode =
  | 'study_left_hand_no_timing'
  | 'study_right_hand_no_timing'
  | 'study_two_hands_no_timing'
  | 'play_left_hand_timing'
  | 'play_right_hand_timing'
  | 'play_two_hands_timing';

/**
 * Backend Client Interface
 * All backend communication should go through this interface
 */
export interface BackendClient {
  // MIDI Commands
  listMidiDevices(): Promise<MidiDeviceInfo[]>;
  startMidiListening(deviceId: string): Promise<void>;
  stopMidiListening(): Promise<void>;
  isMidiConnected(): Promise<boolean>;

  // Lesson Commands
  listLessons(): Promise<LessonMetadata[]>;
  loadLesson(lessonId: string): Promise<Lesson>;

  // Event Listeners (returns cleanup function)
  onMidiChordDetected(callback: (chord: MidiChord) => void): () => void;
  onMidiNoteOff(callback: (midi: number) => void): () => void;
}

/**
 * Injection Token for BackendClient
 * Use this token for dependency injection instead of the interface
 */
export const BACKEND_CLIENT = new InjectionToken<BackendClient>('BackendClient');

/**
 * Backend Client Error
 * Standardized error type for backend operations
 */
export class BackendClientError extends Error {
  constructor(
    message: string,
    public code?: string,
    public details?: unknown
  ) {
    super(message);
    this.name = 'BackendClientError';
  }
}

export interface SingleNoteDTO {
    midi: number;
    duration: number;
    hand: string;
    accidental?: string;
}

/**
 * Chord - has `midi` as array of numbers
 */
export interface ChordNoteDTO {
    midi: number[];
    duration: number;
    hand: string;
    chord?: string;
}

/**
 * Rest - only has duration, no midi
 */
export interface RestNoteDTO {
    duration: number;
}

/**
 * Note union type - matches Rust's #[serde(untagged)] NoteDTO enum
 */
export type NoteDTO = SingleNoteDTO | ChordNoteDTO | RestNoteDTO;

/**
 * Type guards for note discrimination
 */
export function isSingleNote(note: NoteDTO): note is SingleNoteDTO {
    const obj = note as unknown as Record<string, unknown>;
    return 'midi' in note && typeof obj['midi'] === 'number' && 'hand' in note;
}

export function isChordNote(note: NoteDTO): note is ChordNoteDTO {
    const obj = note as unknown as Record<string, unknown>;
    return 'midi' in note && Array.isArray(obj['midi']);
}

export function isRestNote(note: NoteDTO): note is RestNoteDTO {
    return !('midi' in note) && 'duration' in note;
}

/**
 * Convert MIDI number to note name (e.g., 60 -> "C4")
 */
export function midiToNoteName(midi: number): string {
    const noteNames = ['C', 'C#', 'D', 'D#', 'E', 'F', 'F#', 'G', 'G#', 'A', 'A#', 'B'];
    const octave = Math.floor(midi / 12) - 1;
    const noteName = noteNames[midi % 12];
    return `${noteName}${octave}`;
}

/**
 * Get all MIDI numbers from a note (works for single notes and chords)
 */
export function getMidiNumbers(note: NoteDTO): number[] {
    if (isSingleNote(note)) {
        return [note.midi];
    }
    if (isChordNote(note)) {
        return note.midi;
    }
    // It's a rest
    return [];
}

import { CommonModule } from '@angular/common';
import { Component, Input, OnChanges, SimpleChanges, computed, signal } from '@angular/core';
import { LessonDTO, MeasureDTO } from '../../core/models/lesson.model';
import { ChordNoteDTO, NoteDTO, RestNoteDTO, SingleNoteDTO, isChordNote, isRestNote, isSingleNote } from '../../core/models/note.model';
import { StaffComponent, StaffNote } from '../../shared/components/staff/staff.component';

/**
 * Represents a line of music with both treble and bass notes
 */
interface StaffLine {
    trebleNotes: StaffNote[];
    bassNotes: StaffNote[];
    globalStartIndex: number;
    globalBeatOffset: number; // Beat position where this line starts
    isLastLine: boolean;
}

/**
 * Grand Staff Component
 * Renders both treble (right hand) and bass (left hand) staves
 * with notes from a lesson, paired together line by line
 */
@Component({
    selector: 'app-grand-staff',
    standalone: true,
    imports: [CommonModule, StaffComponent],
    template: `
        <div class="grand-staff">
            <!-- Render each line as a treble/bass pair -->
            @for (line of staffLines(); track line.globalStartIndex; let i = $index) {
                <div class="staff-line-pair">
                    <!-- Treble Staff -->
                    <app-staff
                        [width]="staffWidth"
                        [height]="staffHeight"
                        [notes]="line.trebleNotes"
                        [activeNotes]="trebleActiveNotes()"
                        [currentNoteIndex]="currentNoteIndex"
                        [playheadPosition]="playheadPosition"
                        [playheadBeatPosition]="playheadBeatPosition"
                        [highlightNoteIndex]="highlightNoteIndex"
                        [isPlaying]="isPlaying"
                        [globalNoteOffset]="line.globalStartIndex"
                        [globalBeatOffset]="line.globalBeatOffset"
                        [isLastLine]="line.isLastLine"
                        [timeSignature]="lesson?.time_signature || null"
                        clef="treble">
                    </app-staff>

                    <!-- Bass Staff (close to treble) -->
                    <app-staff
                        [width]="staffWidth"
                        [height]="staffHeight"
                        [notes]="line.bassNotes"
                        [activeNotes]="bassActiveNotes()"
                        [currentNoteIndex]="currentNoteIndex"
                        [playheadPosition]="playheadPosition"
                        [playheadBeatPosition]="playheadBeatPosition"
                        [highlightNoteIndex]="highlightNoteIndex"
                        [isPlaying]="isPlaying"
                        [globalNoteOffset]="line.globalStartIndex"
                        [globalBeatOffset]="line.globalBeatOffset"
                        [isLastLine]="line.isLastLine"
                        [timeSignature]="lesson?.time_signature || null"
                        clef="bass">
                    </app-staff>

                    <!-- Spacer between line pairs -->
                    @if (!line.isLastLine) {
                        <div class="line-spacer"></div>
                    }
                </div>
            }
        </div>
    `,
    styles: [`
        .grand-staff {
            padding: 0.5rem;
            background: #fafafa;
            border-radius: 8px;
            position: relative;
            overflow-x: auto;
        }

        .staff-line-pair {
            margin-bottom: 0;
            min-width: 900px;
        }

        .staff-line-pair app-staff:last-of-type {
            /* Add small gap between treble and bass staves */
            margin-top: 8px;
        }

        .line-spacer {
            height: 1rem;
            margin: 0.5rem 0;
        }

        app-staff {
            display: block;
        }
    `]
})
export class GrandStaffComponent implements OnChanges {
    @Input() lesson: LessonDTO | null = null;
    @Input() activeNotes: number[] = [];
    @Input() currentMeasureIndex = 0;
    @Input() currentNoteIndex = -1;
    @Input() playheadPosition = -1;
    @Input() playheadBeatPosition = -1; // Smooth playhead position in beats
    @Input() highlightNoteIndex = -1; // Only highlight note at this global index
    @Input() isPlaying = false;

    staffWidth = 900;
    staffHeight = 80;
    measuresPerLine = 4; // Fixed number of measures per line for even bars

    // Signals for reactive updates
    private _staffLines = signal<StaffLine[]>([]);
    private _currentMeasure = signal<MeasureDTO | null>(null);
    private _activeNotes = signal<number[]>([]);

    staffLines = this._staffLines.asReadonly();
    currentMeasure = this._currentMeasure.asReadonly();

    // Filter active notes by clef range
    trebleActiveNotes = computed(() =>
        this._activeNotes().filter(n => n >= 60)
    );

    bassActiveNotes = computed(() =>
        this._activeNotes().filter(n => n < 60)
    );

    ngOnChanges(changes: SimpleChanges) {
        if (changes['activeNotes']) {
            this._activeNotes.set(this.activeNotes);
        }
        if (changes['lesson'] || changes['currentMeasureIndex']) {
            this.processLesson();
        }
    }

    private processLesson() {
        if (!this.lesson) {
            this._staffLines.set([]);
            this._currentMeasure.set(null);
            return;
        }

        const measures = this.lesson.measures;
        const currentMeasure = measures[this.currentMeasureIndex] || measures[0];
        this._currentMeasure.set(currentMeasure);

        // Split into lines with paired treble/bass staves
        const lines = this.splitIntoLines();
        this._staffLines.set(lines);
    }

    private splitIntoLines(): StaffLine[] {
        if (!this.lesson) return [];

        const lines: StaffLine[] = [];
        let currentLine: { treble: StaffNote[]; bass: StaffNote[]; startIdx: number; beatOffset: number } = {
            treble: [],
            bass: [],
            startIdx: 0,
            beatOffset: 0
        };
        let globalIdx = 0;
        let globalBeatPosition = 0;
        let measuresInCurrentLine = 0;

        for (let measureIdx = 0; measureIdx < this.lesson.measures.length; measureIdx++) {
            const measure = this.lesson.measures[measureIdx];
            const noteCount = measure.notes.length;

            // Check if we've reached the max measures per line
            // If so, finalize current line first (but only if it has content)
            if (measuresInCurrentLine >= this.measuresPerLine && currentLine.treble.length > 0) {
                // Finalize current line
                lines.push({
                    trebleNotes: currentLine.treble,
                    bassNotes: currentLine.bass,
                    globalStartIndex: currentLine.startIdx,
                    globalBeatOffset: currentLine.beatOffset,
                    isLastLine: false
                });

                // Start new line
                currentLine = {
                    treble: [],
                    bass: [],
                    startIdx: globalIdx,
                    beatOffset: globalBeatPosition
                };
                measuresInCurrentLine = 0;
            }

            // Add all notes from this measure to current line
            for (let noteIdx = 0; noteIdx < noteCount; noteIdx++) {
                const note = measure.notes[noteIdx];
                const staffNote = this.convertToStaffNote(note);

                if (staffNote) {
                    staffNote.measureEnd = noteIdx === noteCount - 1;

                    const isTreble = this.isTrebleNote(note, staffNote);
                    const isBass = this.isBassNote(note, staffNote);

                    // Add to treble staff (visible if treble note or rest, hidden otherwise)
                    currentLine.treble.push({
                        ...staffNote,
                        hidden: !isTreble && !staffNote.isRest
                    });

                    // Add to bass staff (visible if bass note, hidden otherwise)
                    // Rests only show on treble to avoid duplication
                    currentLine.bass.push({
                        ...staffNote,
                        hidden: !isBass,
                        isRest: false // Don't show rests on bass (they're on treble)
                    });

                    // Track beat position
                    globalBeatPosition += staffNote.durationValue ?? 1;
                }

                globalIdx++;
            }

            // Count this measure
            measuresInCurrentLine++;
        }

        // Don't forget the last line
        if (currentLine.treble.length > 0) {
            lines.push({
                trebleNotes: currentLine.treble,
                bassNotes: currentLine.bass,
                globalStartIndex: currentLine.startIdx,
                globalBeatOffset: currentLine.beatOffset,
                isLastLine: true
            });
        }

        // Mark the actual last line
        if (lines.length > 0) {
            lines.forEach((line, idx) => {
                line.isLastLine = idx === lines.length - 1;
            });
        }

        return lines;
    }

    private isTrebleNote(note: NoteDTO, staffNote: StaffNote): boolean {
        if (staffNote.isRest) return false;

        // Check explicit hand assignment
        if ('hand' in note) {
            if (note.hand === 'right') return true;
            if (note.hand === 'left') return false;
        }

        // Check explicit staff assignment
        if ('staff' in note) {
            if ((note as any).staff === 0) return true;
            if ((note as any).staff === 1) return false;
        }

        // Auto-assign based on MIDI pitch (split at Middle C = 60)
        const midiValues = Array.isArray(staffNote.midi)
            ? staffNote.midi
            : [staffNote.midi];

        return midiValues.some(m => m >= 60);
    }

    private isBassNote(note: NoteDTO, staffNote: StaffNote): boolean {
        if (staffNote.isRest) return false;

        // Check explicit hand assignment
        if ('hand' in note) {
            if (note.hand === 'left') return true;
            if (note.hand === 'right') return false;
        }

        // Check explicit staff assignment
        if ('staff' in note) {
            if ((note as any).staff === 1) return true;
            if ((note as any).staff === 0) return false;
        }

        // Auto-assign based on MIDI pitch
        const midiValues = Array.isArray(staffNote.midi)
            ? staffNote.midi
            : [staffNote.midi];

        return midiValues.some(m => m < 60);
    }

    private convertToStaffNote(note: NoteDTO): StaffNote | null {
        if (isRestNote(note)) {
            const rest = note as RestNoteDTO;
            return {
                midi: 0,
                duration: this.durationToType(rest.duration),
                durationValue: rest.duration,
                isRest: true
            };
        }

        if (isSingleNote(note)) {
            const single = note as SingleNoteDTO;
            return {
                midi: single.midi,
                duration: this.durationToType(single.duration),
                durationValue: single.duration
            };
        }

        if (isChordNote(note)) {
            const chord = note as ChordNoteDTO;
            return {
                midi: chord.midi,
                duration: this.durationToType(chord.duration),
                durationValue: chord.duration
            };
        }

        return null;
    }

    private durationToType(duration: number): string {
        if (duration >= 4) return 'whole';
        if (duration >= 2) return 'half';
        if (duration >= 1) return 'quarter';
        if (duration >= 0.5) return 'eighth';
        return 'sixteenth';
    }
}

import { CommonModule } from '@angular/common';
import {
    AfterViewInit,
    Component,
    ElementRef,
    inject,
    Input,
    OnChanges,
    SimpleChanges,
    ViewChild,
} from '@angular/core';
import { TimeSignatureRendererService } from '../../../features/lesson-player/notation-stage/time-signature-renderer.service';
import { ClefRendererService } from '../../../features/lesson-player/notation-stage/clef-renderer.service';
import { RestRendererService } from '../../../features/lesson-player/notation-stage/rest-renderer.service';
import { NoteheadRendererService } from '../../../features/lesson-player/notation-stage/notehead-renderer.service';

/**
 * Music Staff Component
 * Renders a single staff line (treble or bass) with notes using Canvas API
 * Single-line only - GrandStaffComponent handles multi-line pairing
 *
 * Y-Axis Inversion: Higher pitch = Lower Y value on screen
 */
@Component({
    selector: 'app-staff',
    standalone: true,
    imports: [CommonModule],
    template: `
        <canvas
            #staffCanvas
            [width]="width"
            [height]="height"
            class="staff-canvas"
        >
        </canvas>
    `,
    styles: [
        `
            .staff-canvas {
                background: #0f0f23;
                display: block;
            }
        `,
    ],
})
export class StaffComponent implements AfterViewInit, OnChanges {
    @ViewChild('staffCanvas') canvas!: ElementRef<HTMLCanvasElement>;

    @Input() width = 900;
    @Input() height = 80;
    @Input() notes: StaffNote[] = [];
    @Input() activeNotes: number[] = [];
    @Input() clef: 'treble' | 'bass' = 'treble';
    @Input() currentNoteIndex = -1;
    @Input() playheadPosition = -1;
    @Input() playheadBeatPosition = -1; // Smooth playhead position in beats (-1 = hidden)
    @Input() highlightNoteIndex = -1; // Only highlight notes at this global index
    @Input() isPlaying = false;
    @Input() globalNoteOffset = 0;
    @Input() isLastLine = false;
    @Input() globalBeatOffset = 0; // Beat offset for this staff line (for multi-line)
    @Input() timeSignature: string | null = null; // Time signature like "4/4"
    @Input() showFirstBar = false; // Show time signature on first measure only

    private ctx!: CanvasRenderingContext2D;
    private timeSignatureRenderer = inject(TimeSignatureRendererService);
    private clefRenderer = inject(ClefRendererService);
    private restRenderer = inject(RestRendererService);
    private noteheadRenderer = inject(NoteheadRendererService);

    // Layout constants
    private readonly LINE_SPACING = 12;
    private readonly TOP_MARGIN = 15;
    private readonly LEFT_MARGIN = 110; // Increased to make room for clef and time signature
    private readonly RIGHT_MARGIN = 30;
    private readonly STEM_HEIGHT = 35;
    private readonly BAR_LINE_SPACE = 15;

    ngAfterViewInit() {
        const canvas = this.canvas.nativeElement;
        this.ctx = canvas.getContext('2d')!;
        this.render();
    }

    ngOnChanges(_changes: SimpleChanges) {
        if (this.ctx) {
            this.render();
        }
    }

    private render() {
        if (!this.ctx) return;

        this.clearCanvas();
        this.drawStaffLines();
        this.drawClef();
        this.drawTimeSignature();
        this.drawNotes();
        this.drawSmoothPlayhead();
    }

    private clearCanvas() {
        this.ctx.clearRect(0, 0, this.width, this.height);
    }

    private drawStaffLines() {
        this.ctx.strokeStyle = '#ffffff';
        this.ctx.lineWidth = 1;

        for (let i = 0; i < 5; i++) {
            const y = this.TOP_MARGIN + i * this.LINE_SPACING;
            this.ctx.beginPath();
            this.ctx.moveTo(20, y);
            this.ctx.lineTo(this.width - 20, y);
            this.ctx.stroke();
        }
    }

    /**
     * Get Y coordinate for a staff line
     * NOTE: lineIndex is FROM TOP (0 = top line, 4 = bottom line)
     * BUT we always think in terms of FROM BOTTOM in notation logic!
     * Line 0 (top) = Line 5 from bottom
     * Line 1 = Line 4 from bottom
     * Line 2 (middle) = Line 3 from bottom
     * Line 3 = Line 2 from bottom
     * Line 4 (bottom) = Line 1 from bottom
     */
    private getLineY(lineIndex: number): number {
        return this.TOP_MARGIN + lineIndex * this.LINE_SPACING;
    }

    private getStaffMiddleY(): number {
        return this.getLineY(2);
    }

    private getStaffBottomY(): number {
        return this.getLineY(4);
    }

    private drawClef() {
        // Standardized clef position - matches notation-stage component
        const anchorX = 30;

        if (this.clef === 'treble') {
            // Treble clef: anchor at G4 line (2nd from bottom = line 3 from top)
            const anchorY = this.getLineY(3);
            this.clefRenderer.drawTrebleClef(
                this.ctx,
                anchorX,
                anchorY,
                this.LINE_SPACING,
                1.0,
                '#ffffff'
            );
        } else {
            // Bass clef: anchor at F3 line (4th from bottom = line 1 from top)
            const anchorY = this.getLineY(1);
            this.clefRenderer.drawBassClef(
                this.ctx,
                anchorX,
                anchorY,
                this.LINE_SPACING,
                1.0,
                '#ffffff'
            );
        }
    }

    private drawTimeSignature() {
        // Only draw on first staff line (when globalBeatOffset is 0)
        if (!this.timeSignature || this.globalBeatOffset !== 0) return;

        // Parse time signature
        const parts = this.timeSignature.split('/');
        if (parts.length !== 2) return;

        const numerator = parseInt(parts[0], 10);
        const denominator = parseInt(parts[1], 10);

        if (isNaN(numerator) || isNaN(denominator)) return;

        // Time signature position - adjusted for smaller staff line spacing
        const timeSignatureX = 70;

        this.timeSignatureRenderer.drawTimeSignature(
            this.ctx,
            timeSignatureX,
            this.TOP_MARGIN,
            this.LINE_SPACING,
            numerator,
            denominator,
            '#ffffff'
        );
    }

    /**
     * Convert duration string to numeric beats value
     */
    private durationToBeats(duration: string): number {
        switch (duration) {
            case 'whole': return 4;
            case 'half': return 2;
            case 'quarter': return 1;
            case 'eighth': return 0.5;
            case 'sixteenth': return 0.25;
            default: return 1;
        }
    }

    /**
     * Calculate note positions with equal measure widths and proportional note spacing within measures
     * Returns array of x positions for each note
     */
    private calculateNotePositions(): number[] {
        if (this.notes.length === 0) return [];

        // First: identify measures and their note ranges
        interface MeasureInfo {
            startIdx: number;
            endIdx: number;
            totalDuration: number;
        }

        const measures: MeasureInfo[] = [];
        let measureStart = 0;

        for (let i = 0; i < this.notes.length; i++) {
            if (this.notes[i].measureEnd || i === this.notes.length - 1) {
                // Calculate total duration for this measure
                let totalDuration = 0;
                for (let j = measureStart; j <= i; j++) {
                    const note = this.notes[j];
                    const duration = note.durationValue ?? this.durationToBeats(note.duration);
                    totalDuration += duration;
                }

                measures.push({
                    startIdx: measureStart,
                    endIdx: i,
                    totalDuration
                });
                measureStart = i + 1;
            }
        }

        // Calculate available width and width per measure
        const availableWidth = this.width - this.LEFT_MARGIN - this.RIGHT_MARGIN;
        const barLineCount = measures.length - 1; // Bar lines between measures
        const totalBarLineSpace = barLineCount * this.BAR_LINE_SPACE;
        const widthForMeasures = availableWidth - totalBarLineSpace;
        const measureWidth = widthForMeasures / measures.length;

        // Calculate positions: equal measure widths, proportional spacing within each measure
        const positions: number[] = new Array(this.notes.length);
        let measureStartX = this.LEFT_MARGIN;

        for (const measure of measures) {
            const noteCount = measure.endIdx - measure.startIdx + 1;

            if (noteCount === 1) {
                // Single note in measure - center it
                positions[measure.startIdx] = measureStartX + measureWidth * 0.1;
            } else {
                // Multiple notes - distribute proportionally based on duration
                // Leave some padding at start and end of measure
                const padding = measureWidth * 0.05;
                const usableWidth = measureWidth - padding * 2;

                // Calculate cumulative duration positions
                let cumulativeDuration = 0;
                for (let i = measure.startIdx; i <= measure.endIdx; i++) {
                    const note = this.notes[i];
                    const duration = note.durationValue ?? this.durationToBeats(note.duration);

                    // Position based on when in the measure this note starts
                    const positionRatio = cumulativeDuration / measure.totalDuration;
                    positions[i] = measureStartX + padding + (usableWidth * positionRatio);

                    cumulativeDuration += duration;
                }
            }

            // Move to next measure
            measureStartX += measureWidth + this.BAR_LINE_SPACE;
        }

        return positions;
    }

    private drawNotes() {
        if (this.notes.length === 0) return;

        const positions = this.calculateNotePositions();

        // Calculate measure width for bar line positioning
        const measureCount = this.notes.filter(n => n.measureEnd).length + (this.notes[this.notes.length - 1]?.measureEnd ? 0 : 1);
        const availableWidth = this.width - this.LEFT_MARGIN - this.RIGHT_MARGIN;
        const barLineCount = Math.max(0, measureCount - 1);
        const totalBarLineSpace = barLineCount * this.BAR_LINE_SPACE;
        const measureWidth = (availableWidth - totalBarLineSpace) / measureCount;

        let measureIndex = 0;

        this.notes.forEach((note, localIndex) => {
            const globalIndex = this.globalNoteOffset + localIndex;
            const x = positions[localIndex];

            // Draw the note (unless hidden - hidden notes still reserve space)
            if (!note.hidden) {
                if (note.isRest) {
                    this.drawRest(x, note.duration);
                } else {
                    const midiValues = Array.isArray(note.midi) ? note.midi : [note.midi];
                    for (const midi of midiValues) {
                        const y = this.midiToY(midi);
                        // Only highlight if this is the current note position AND the midi is being played
                        const isActive = globalIndex === this.highlightNoteIndex && this.activeNotes.includes(midi);
                        this.drawLedgerLines(x, midi);
                        this.drawNote(x, y, note.duration, isActive);
                    }
                }

                // Draw current note cursor (only for visible notes)
                if (globalIndex === this.currentNoteIndex && !this.isPlaying) {
                    this.drawCurrentNoteCursor(x);
                }

                // Draw playhead (only for visible notes)
                if (globalIndex === this.playheadPosition) {
                    this.drawPlayhead(x);
                }
            }

            // Draw bar line after measure end (except for last note)
            if (note.measureEnd && localIndex < this.notes.length - 1) {
                // Bar line at fixed position based on equal measure widths
                const barLineX = this.LEFT_MARGIN + (measureIndex + 1) * measureWidth + measureIndex * this.BAR_LINE_SPACE + this.BAR_LINE_SPACE / 2;
                this.drawBarLine(barLineX);
                measureIndex++;
            }
        });

        // Draw end bar line for the last line
        if (this.isLastLine && this.notes.length > 0) {
            this.drawEndBarLine(this.width - this.RIGHT_MARGIN);
        }
    }

    private drawBarLine(x: number): void {
        this.ctx.strokeStyle = '#ffffff';
        this.ctx.lineWidth = 1.5;

        const topY = this.getLineY(0);
        const bottomY = this.getLineY(4);

        this.ctx.beginPath();
        this.ctx.moveTo(x, topY);
        this.ctx.lineTo(x, bottomY);
        this.ctx.stroke();
    }

    private drawEndBarLine(x: number): void {
        const topY = this.getLineY(0);
        const bottomY = this.getLineY(4);

        // Thin line
        this.ctx.strokeStyle = '#ffffff';
        this.ctx.lineWidth = 1.5;
        this.ctx.beginPath();
        this.ctx.moveTo(x - 6, topY);
        this.ctx.lineTo(x - 6, bottomY);
        this.ctx.stroke();

        // Thick line
        this.ctx.lineWidth = 4;
        this.ctx.beginPath();
        this.ctx.moveTo(x, topY);
        this.ctx.lineTo(x, bottomY);
        this.ctx.stroke();
    }

    private drawNote(x: number, y: number, duration: string, active: boolean) {
        // Convert duration string to beats
        const durationBeats = this.durationToBeats(duration);

        // Draw notehead using shared renderer service
        const color = active ? '#2196F3' : '#ffffff';
        this.noteheadRenderer.drawNotehead(this.ctx, x, y, color, active, durationBeats, false);

        // Draw stem (all notes except whole notes) using centralized service
        if (duration !== 'whole') {
            const stemUp = y > this.getStaffMiddleY();
            this.noteheadRenderer.drawStem(this.ctx, x, y, color, stemUp, durationBeats, this.STEM_HEIGHT);
        }
    }

    private drawLedgerLines(x: number, midi: number) {
        const y = this.midiToY(midi);
        const topLine = this.getLineY(0);
        const bottomLine = this.getLineY(4);

        this.ctx.strokeStyle = '#ffffff';
        this.ctx.lineWidth = 1;

        // Above staff
        if (y < topLine) {
            let ledgerY = topLine - this.LINE_SPACING;
            while (ledgerY >= y - this.LINE_SPACING / 2) {
                this.ctx.beginPath();
                this.ctx.moveTo(x - 12, ledgerY);
                this.ctx.lineTo(x + 12, ledgerY);
                this.ctx.stroke();
                ledgerY -= this.LINE_SPACING;
            }
        }

        // Below staff
        if (y > bottomLine) {
            let ledgerY = bottomLine + this.LINE_SPACING;
            while (ledgerY <= y + this.LINE_SPACING / 2) {
                this.ctx.beginPath();
                this.ctx.moveTo(x - 12, ledgerY);
                this.ctx.lineTo(x + 12, ledgerY);
                this.ctx.stroke();
                ledgerY += this.LINE_SPACING;
            }
        }
    }

    private drawRest(x: number, duration: string) {
        // Convert duration string to beats value
        const durationBeats = this.durationToBeats(duration);

        // Use shared RestRendererService for consistent rendering
        this.restRenderer.drawRest(
            this.ctx,
            x,
            this.TOP_MARGIN,
            this.LINE_SPACING,
            durationBeats,
            '#ffffff'
        );
    }

    /**
     * Convert MIDI note number to Y coordinate on staff
     * ALWAYS CALCULATE FROM BOTTOM!
     *
     * Reference notes (anchors):
     * - Treble clef: G4 (MIDI 67) on line 2 from bottom
     * - Bass clef: F3 (MIDI 53) on line 4 from bottom
     */
    private midiToY(midi: number): number {
        // Use correct reference notes from ClefRendererService
        // Treble: G4 (67) on 2nd line from bottom (line index 1)
        // Bass: F3 (53) on 4th line from bottom (line index 3)
        const referenceNote = this.clef === 'treble' ? 67 : 53; // G4 / F3
        const referenceLineIndex = this.clef === 'treble' ? 1 : 3; // 2nd / 4th line from bottom

        const steps = this.semitonesToSteps(midi) - this.semitonesToSteps(referenceNote);
        const halfSpacing = this.LINE_SPACING / 2;
        const referenceY = this.getLineY(4 - referenceLineIndex); // Convert from bottom to top indexing

        return referenceY - steps * halfSpacing;
    }

    private semitonesToSteps(midi: number): number {
        const octave = Math.floor(midi / 12);
        const noteInOctave = midi % 12;
        const stepMap = [0, 0, 1, 1, 2, 3, 3, 4, 4, 5, 5, 6];
        return octave * 7 + stepMap[noteInOctave];
    }

    private drawCurrentNoteCursor(x: number): void {
        this.ctx.save();

        const pulse = 0.8 + 0.2 * Math.sin(Date.now() / 300);
        this.ctx.strokeStyle = `rgba(255, 152, 0, ${pulse})`;
        this.ctx.lineWidth = 3;

        const cursorWidth = 30;
        const cursorHeight = 70;
        const cursorX = x - cursorWidth / 2;
        const cursorY = this.getLineY(0) - 10;

        this.ctx.beginPath();
        this.ctx.roundRect(cursorX, cursorY, cursorWidth, cursorHeight, 8);
        this.ctx.stroke();
        this.ctx.fillStyle = `rgba(255, 152, 0, ${pulse * 0.1})`;
        this.ctx.fill();

        this.ctx.restore();
    }

    private drawPlayhead(x: number): void {
        this.ctx.save();

        const topY = this.getLineY(0) - 15;
        const bottomY = this.getLineY(4) + 15;

        // Main line
        this.ctx.strokeStyle = '#E91E63';
        this.ctx.lineWidth = 3;
        this.ctx.lineCap = 'round';
        this.ctx.beginPath();
        this.ctx.moveTo(x, topY);
        this.ctx.lineTo(x, bottomY);
        this.ctx.stroke();

        // Triangle
        this.ctx.fillStyle = '#E91E63';
        this.ctx.beginPath();
        this.ctx.moveTo(x - 8, topY - 10);
        this.ctx.lineTo(x + 8, topY - 10);
        this.ctx.lineTo(x, topY);
        this.ctx.closePath();
        this.ctx.fill();

        // Glow
        this.ctx.shadowColor = '#E91E63';
        this.ctx.shadowBlur = 10;
        this.ctx.strokeStyle = 'rgba(233, 30, 99, 0.5)';
        this.ctx.lineWidth = 6;
        this.ctx.beginPath();
        this.ctx.moveTo(x, topY);
        this.ctx.lineTo(x, bottomY);
        this.ctx.stroke();

        this.ctx.restore();
    }

    /**
     * Draw smooth playhead based on beat position
     * This allows the playhead to move smoothly between notes
     */
    private drawSmoothPlayhead(): void {
        if (this.playheadBeatPosition < 0 || this.notes.length === 0) return;

        // Calculate total beats on this staff line
        let totalBeats = 0;
        const noteBeatPositions: { startBeat: number; endBeat: number; noteIndex: number }[] = [];

        for (let i = 0; i < this.notes.length; i++) {
            const note = this.notes[i];
            const duration = note.durationValue ?? this.durationToBeats(note.duration);
            noteBeatPositions.push({
                startBeat: totalBeats,
                endBeat: totalBeats + duration,
                noteIndex: i
            });
            totalBeats += duration;
        }

        // Adjust playhead position relative to this staff line's beat offset
        const localBeatPosition = this.playheadBeatPosition - this.globalBeatOffset;

        // Check if playhead is within this staff line's range
        if (localBeatPosition < 0 || localBeatPosition > totalBeats) return;

        // Calculate X position based on beat position
        const x = this.calculateXFromBeatPosition(localBeatPosition, noteBeatPositions);
        if (x < 0) return;

        // Draw the playhead at the calculated position
        this.drawPlayhead(x);
    }

    /**
     * Calculate X position from a beat position
     */
    private calculateXFromBeatPosition(
        beatPosition: number,
        noteBeatPositions: { startBeat: number; endBeat: number; noteIndex: number }[]
    ): number {
        if (noteBeatPositions.length === 0) return -1;

        const positions = this.calculateNotePositions();

        // Find which note this beat position falls within
        for (let i = 0; i < noteBeatPositions.length; i++) {
            const { startBeat, endBeat, noteIndex } = noteBeatPositions[i];

            if (beatPosition >= startBeat && beatPosition < endBeat) {
                // Interpolate within this note's duration
                const noteProgress = (beatPosition - startBeat) / (endBeat - startBeat);
                const currentX = positions[noteIndex];

                // Get next note's X position for interpolation
                let nextX: number;
                if (noteIndex + 1 < this.notes.length) {
                    nextX = positions[noteIndex + 1];
                } else {
                    // Last note - extrapolate to end of staff
                    nextX = this.width - this.RIGHT_MARGIN;
                }

                // Interpolate between current and next note position
                return currentX + (nextX - currentX) * noteProgress;
            }
        }

        // If past all notes, return position at end
        if (beatPosition >= noteBeatPositions[noteBeatPositions.length - 1].endBeat) {
            return this.width - this.RIGHT_MARGIN;
        }

        return positions[0]; // Default to first note
    }
}

/**
 * Staff note with measure boundary info
 */
export interface StaffNote {
    midi: number | number[];
    duration: string;
    durationValue?: number; // Numeric duration in beats (1 = quarter, 2 = half, 4 = whole)
    isRest?: boolean;
    measureEnd?: boolean;
    hidden?: boolean; // If true, note position is reserved but nothing is drawn
}

export interface User {
  name: string;
}

export interface UserProgress {
  level: number;           // Player level (1-100)
  xp: number;             // Current XP within this level
  xpToNextLevel: number;  // XP needed for next level
  totalXP: number;        // Lifetime XP earned
}

export interface XPGain {
  amount: number;
  reason: string;
  levelUp: boolean;
  newLevel?: number;
}

/**
 * XP reward amounts for different actions
 */
export const XPRewards = {
  PERFECT_NOTE: 10,
  GOOD_NOTE: 5,
  CORRECT_NOTE: 3,
  WRONG_NOTE: 0,
  COMPLETE_LESSON: 100,
  PERFECT_LESSON: 200,    // 100% accuracy
  DAILY_PRACTICE: 50,
  WEEKLY_STREAK: 200,
  ACHIEVEMENT_UNLOCK: 50
} as const;

/**
 * Calculate XP needed for a level
 * Uses exponential curve: level^2 * 100
 */
export function calculateXPForLevel(level: number): number {
  return Math.floor(Math.pow(level, 2) * 100);
}

/**
 * Calculate level from total XP
 */
export function calculateLevelFromXP(totalXP: number): number {
  let level = 1;
  let xpRequired = 0;

  while (xpRequired <= totalXP) {
    level++;
    xpRequired += calculateXPForLevel(level - 1);
  }

  return Math.max(1, level - 1);
}

/**
 * Calculate current XP within level
 */
export function calculateCurrentXP(totalXP: number, level: number): number {
  let xpRequired = 0;
  for (let i = 1; i < level; i++) {
    xpRequired += calculateXPForLevel(i);
  }
  return totalXP - xpRequired;
}

export type NoteState = 'upcoming' | 'active' | 'hit' | 'missed';

/**
 * Timing feedback for note performance
 * - perfect: Hit within the timing window
 * - early: Pressed before the note should have started
 * - late: Started playing after the note should have started
 * - early_release: Released the key before the note duration ended
 * - replayed: Released and pressed again during the same note
 */
export type TimingFeedback = 'perfect' | 'early' | 'late' | 'early_release' | 'replayed' | null;

/**
 * Represents a note or chord in the scrolling player
 */
export interface ScrollingNote {
    /** MIDI note numbers (single note = 1 element, chord = multiple) */
    midi: number[];
    /** Start position in beats from beginning of lesson */
    startBeat: number;
    /** Duration in beats */
    durationBeats: number;
    /** Current rendering/evaluation state */
    state: NoteState;
    /** Which hand plays this note */
    hand: 'left' | 'right';
    /** Whether this is a rest (no sound) */
    isRest: boolean;
    /** Timing feedback (null = not evaluated yet) */
    timingFeedback?: TimingFeedback;
    /** Beat position when the note was actually hit (for late detection) */
    hitBeat?: number;
    /** Whether the note was released early (before duration ended) */
    releasedEarly?: boolean;
    /** Whether the note was replayed after release */
    wasReplayed?: boolean;
}

