import { Injectable, signal, computed, inject } from '@angular/core';
import {
  UserProgress,
  XPGain,
  XPRewards,
  calculateXPForLevel,
  calculateLevelFromXP,
  calculateCurrentXP
} from '../models/progress.model';
import { SoundService } from './sound.service';

/**
 * Progress Service
 * Manages user XP, levels, and progression
 */
@Injectable({
  providedIn: 'root'
})
export class ProgressService {
  private soundService = inject(SoundService);

  // State
  private readonly _totalXP = signal(0);
  private readonly _lastXPGain = signal<XPGain | null>(null);

  // Computed values
  readonly totalXP = this._totalXP.asReadonly();
  readonly lastXPGain = this._lastXPGain.asReadonly();

  readonly progress = computed<UserProgress>(() => {
    const total = this._totalXP();
    const level = calculateLevelFromXP(total);
    const currentXP = calculateCurrentXP(total, level);
    const xpToNext = calculateXPForLevel(level);

    return {
      level,
      xp: currentXP,
      xpToNextLevel: xpToNext,
      totalXP: total
    };
  });

  readonly progressPercent = computed(() => {
    const prog = this.progress();
    return Math.round((prog.xp / prog.xpToNextLevel) * 100);
  });

  constructor() {
    // Load from localStorage
    this.loadProgress();
  }

  /**
   * Award XP to the user
   */
  awardXP(amount: number, reason: string): XPGain {
    const oldLevel = this.progress().level;
    const newTotalXP = this._totalXP() + amount;
    this._totalXP.set(newTotalXP);

    const newLevel = calculateLevelFromXP(newTotalXP);
    const levelUp = newLevel > oldLevel;

    const gain: XPGain = {
      amount,
      reason,
      levelUp,
      newLevel: levelUp ? newLevel : undefined
    };

    this._lastXPGain.set(gain);
    this.saveProgress();

    console.log(`[Progress] Awarded ${amount} XP for ${reason}. Total: ${newTotalXP} (Level ${newLevel})`);

    // Play level-up sound
    if (levelUp) {
      this.soundService.play('levelUp');
    }

    // Clear last gain after animation
    setTimeout(() => this._lastXPGain.set(null), 3000);

    return gain;
  }

  /**
   * Award XP for note accuracy
   */
  awardNoteXP(pitchCorrect: boolean, isPerfect: boolean = false): XPGain {
    let amount = 0;
    let reason = '';

    if (!pitchCorrect) {
      amount = XPRewards.WRONG_NOTE;
      reason = 'Wrong note';
    } else if (isPerfect) {
      amount = XPRewards.PERFECT_NOTE;
      reason = 'Perfect note!';
    } else {
      amount = XPRewards.CORRECT_NOTE;
      reason = 'Correct note';
    }

    return this.awardXP(amount, reason);
  }

  /**
   * Award XP for lesson completion
   */
  awardLessonXP(accuracy: number): XPGain {
    const isPerfect = accuracy >= 100;
    const amount = isPerfect ? XPRewards.PERFECT_LESSON : XPRewards.COMPLETE_LESSON;
    const reason = isPerfect ? 'Perfect lesson!' : 'Lesson complete';

    return this.awardXP(amount, reason);
  }

  /**
   * Award daily practice bonus
   */
  awardDailyBonus(): XPGain {
    return this.awardXP(XPRewards.DAILY_PRACTICE, 'Daily practice bonus');
  }

  /**
   * Award streak bonus
   */
  awardStreakBonus(days: number): XPGain {
    return this.awardXP(XPRewards.WEEKLY_STREAK, `${days}-day streak!`);
  }

  /**
   * Reset progress (for testing)
   */
  reset(): void {
    this._totalXP.set(0);
    this._lastXPGain.set(null);
    this.saveProgress();
  }

  /**
   * Load progress from localStorage
   */
  private loadProgress(): void {
    const saved = localStorage.getItem('userProgress');
    if (saved) {
      try {
        const data = JSON.parse(saved);
        this._totalXP.set(data.totalXP || 0);
      } catch (e) {
        console.error('[Progress] Failed to load progress:', e);
      }
    }
  }

  /**
   * Save progress to localStorage
   */
  private saveProgress(): void {
    localStorage.setItem('userProgress', JSON.stringify({
      totalXP: this._totalXP()
    }));
  }
}

import { Injectable } from '@angular/core';

/**
 * Rest Renderer Service
 *
 * Використовує Unicode символи для паузів (Bravura font).
 *
 * Типи паузів:
 * - Ціла пауза (4+ beats) - 𝄻 (U+1D13B)
 * - Половинна пауза (2-3.99 beats) - 𝄼 (U+1D13C)
 * - Чвертна пауза (1-1.99 beats) - 𝄽 (U+1D13D)
 * - Восьма пауза (0.5-0.99 beats) - 𝄾 (U+1D13E)
 * - Шістнадцята пауза (0.25-0.49 beats) - 𝄿 (U+1D13F)
 * - 32-га пауза (< 0.25 beats) - 𝅀 (U+1D140)
 */
@Injectable({
  providedIn: 'root'
})
export class RestRendererService {

  // Unicode символи паузів
  private readonly REST_SYMBOLS = {
    whole: '𝄻',      // U+1D13B
    half: '𝄼',       // U+1D13C
    quarter: '𝄽',    // U+1D13D
    eighth: '𝄾',     // U+1D13E
    sixteenth: '𝄿',  // U+1D13F
    thirtySecond: '𝅀' // U+1D140
  };

  // Еталонний lineSpacing, при якому були налаштовані якорі
  private readonly REFERENCE_LINE_SPACING = 35;

  // Якорі пауз (Y offset від центру символу, в пікселях при REFERENCE_LINE_SPACING)
  // Визначені за допомогою Rest Anchor Tuning UI при lineSpacing = 35
  // Якор цілої ноти співпадає з 4 рядком
  // Якор половинної ноти з 3 рядком
  // Якори решти з 3 рядком
  private readonly REST_ANCHOR_OFFSETS = {
    whole: -33,      // Whole rest - line 4 (at lineSpacing=35)
    half: -17,       // Half rest - line 3 (at lineSpacing=35)
    quarter: 0,      // Quarter rest - line 3 (at lineSpacing=35)
    eighth: -20,     // Eighth rest - line 3 (at lineSpacing=35)
    sixteenth: -12,  // Sixteenth rest - line 3 (at lineSpacing=35)
    thirtySecond: -8 // 32nd rest - line 3 (at lineSpacing=35)
  };

  /**
   * Намалювати паузу
   *
   * @param ctx - Canvas context
   * @param x - X координата центру паузи
   * @param staffTop - Y координата верху нотоносця
   * @param lineSpacing - відстань між лініями нотоносця
   * @param duration - тривалість паузи в beats
   * @param color - колір паузи
   */
  drawRest(
    ctx: CanvasRenderingContext2D,
    x: number,
    staffTop: number,
    lineSpacing: number,
    duration: number,
    color: string = '#ffffff'
  ): void {
    // Розрахунок позицій ліній (ЗАВЖДИ РАХУЄМО ВІД НИЗУ!)
    // Line 1 (bottom): staffTop + lineSpacing * 4
    // Line 2: staffTop + lineSpacing * 3
    // Line 3 (middle): staffTop + lineSpacing * 2
    // Line 4: staffTop + lineSpacing * 1
    // Line 5 (top): staffTop + lineSpacing * 0
    const line2 = staffTop + lineSpacing * 3; // Line 2 from bottom
    const line3 = staffTop + lineSpacing * 2; // Line 3 from bottom (middle)
    const line4 = staffTop + lineSpacing * 1; // Line 4 from bottom

    // Розрахувати scale factor для якорів
    const scaleFactor = lineSpacing / this.REFERENCE_LINE_SPACING;

    // Вибрати символ та розмір шрифту
    let symbol: string;
    let fontSize: number;
    let targetLineY: number; // Лінія, до якої прив'язується якір
    let anchorOffset: number; // Offset якоря від центру символу (масштабований)

    if (duration >= 4) {
      // Whole rest - anchor at line 4
      symbol = this.REST_SYMBOLS.whole;
      fontSize = lineSpacing * 2.5;
      targetLineY = line4;
      anchorOffset = this.REST_ANCHOR_OFFSETS.whole * scaleFactor;
    } else if (duration >= 2) {
      // Half rest - anchor at line 3
      symbol = this.REST_SYMBOLS.half;
      fontSize = lineSpacing * 2.5;
      targetLineY = line3;
      anchorOffset = this.REST_ANCHOR_OFFSETS.half * scaleFactor;
    } else if (duration >= 1) {
      // Quarter rest - anchor at line 3
      symbol = this.REST_SYMBOLS.quarter;
      fontSize = lineSpacing * 3.5;
      targetLineY = line3;
      anchorOffset = this.REST_ANCHOR_OFFSETS.quarter * scaleFactor;
    } else if (duration >= 0.5) {
      // Eighth rest - anchor at line 3
      symbol = this.REST_SYMBOLS.eighth;
      fontSize = lineSpacing * 3.5;
      targetLineY = line3;
      anchorOffset = this.REST_ANCHOR_OFFSETS.eighth * scaleFactor;
    } else if (duration >= 0.25) {
      // Sixteenth rest - anchor at line 3
      symbol = this.REST_SYMBOLS.sixteenth;
      fontSize = lineSpacing * 4;
      targetLineY = line3;
      anchorOffset = this.REST_ANCHOR_OFFSETS.sixteenth * scaleFactor;
    } else {
      // 32nd rest - anchor at line 3
      symbol = this.REST_SYMBOLS.thirtySecond;
      fontSize = lineSpacing * 4.5;
      targetLineY = line3;
      anchorOffset = this.REST_ANCHOR_OFFSETS.thirtySecond * scaleFactor;
    }

    // Розрахувати Y позицію центру символу
    // targetLineY - це де повинен бути якір
    // anchorOffset - це відстань від центру до якоря
    // Тому центр = targetLineY - anchorOffset
    const centerY = targetLineY - anchorOffset;

    // Намалювати символ
    ctx.save();
    ctx.fillStyle = color;
    ctx.font = `${fontSize}px Bravura, "Segoe UI Symbol", serif`;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText(symbol, x, centerY);
    ctx.restore();
  }

  /**
   * Отримати назву типу паузи для заданої тривалості
   */
  getRestType(duration: number): string {
    if (duration >= 4) return 'whole';
    if (duration >= 2) return 'half';
    if (duration >= 1) return 'quarter';
    if (duration >= 0.5) return 'eighth';
    if (duration >= 0.25) return 'sixteenth';
    return 'thirty-second';
  }

  /**
   * Отримати Y offset якоря від центру символу паузи
   * Використовується для позиціонування паузи на нотному стані
   *
   * @param duration - тривалість паузи в beats
   * @returns Y offset в пікселях (від центру символу)
   */
  getRestAnchorOffset(duration: number): number {
    if (duration >= 4) return this.REST_ANCHOR_OFFSETS.whole;
    if (duration >= 2) return this.REST_ANCHOR_OFFSETS.half;
    if (duration >= 1) return this.REST_ANCHOR_OFFSETS.quarter;
    if (duration >= 0.5) return this.REST_ANCHOR_OFFSETS.eighth;
    if (duration >= 0.25) return this.REST_ANCHOR_OFFSETS.sixteenth;
    return this.REST_ANCHOR_OFFSETS.thirtySecond;
  }

  /**
   * Отримати Y координату якоря паузи (anchor point)
   * ЗАВЖДИ РАХУЄМО ВІД НИЗУ!
   *
   * @param staffTop - Y координата верху нотоносця
   * @param lineSpacing - відстань між лініями
   * @param duration - тривалість паузи в beats
   * @returns Y координата якоря паузи (де повинна бути прив'язка до лінії)
   */
  getRestY(staffTop: number, lineSpacing: number, duration: number): number {
    // Line calculations (FROM BOTTOM):
    // Line 1 (bottom): staffTop + lineSpacing * 4
    // Line 2: staffTop + lineSpacing * 3
    // Line 3 (middle): staffTop + lineSpacing * 2
    // Line 4: staffTop + lineSpacing * 1
    // Line 5 (top): staffTop + lineSpacing * 0
    const line2 = staffTop + lineSpacing * 3; // Line 2 from bottom
    const line3 = staffTop + lineSpacing * 2; // Line 3 from bottom (middle)
    const line4 = staffTop + lineSpacing * 1; // Line 4 from bottom

    // Повертаємо Y позицію якоря (це targetLineY з drawRest)
    if (duration >= 4) {
      // Whole rest - anchor at line 4
      return line4;
    } else {
      // Half, quarter, eighth, sixteenth, 32nd - anchor at line 3
      return line3;
    }
  }
}

import { Injectable, signal } from '@angular/core';

/**
 * Sound Service
 * Manages audio feedback for gameplay events
 * Uses Web Audio API for low-latency sound playback
 */
@Injectable({
  providedIn: 'root'
})
export class SoundService {
  private audioContext: AudioContext | null = null;
  private enabled = signal(true);
  private volume = signal(0.5);

  // Oscillator-based sounds (no files needed)
  private sounds = {
    perfectNote: this.createPerfectNoteSound.bind(this),
    goodNote: this.createGoodNoteSound.bind(this),
    wrongNote: this.createWrongNoteSound.bind(this),
    levelUp: this.createLevelUpSound.bind(this),
    achievement: this.createAchievementSound.bind(this),
    combo: this.createComboSound.bind(this)
  };

  constructor() {
    // Initialize audio context on first user interaction
    if (typeof window !== 'undefined') {
      document.addEventListener('click', () => this.initAudio(), { once: true });
      document.addEventListener('keydown', () => this.initAudio(), { once: true });
    }
  }

  /**
   * Initialize Web Audio API
   */
  private initAudio(): void {
    if (!this.audioContext) {
      this.audioContext = new AudioContext();
      console.log('[Sound] Audio context initialized');
    }
  }

  /**
   * Play a sound effect
   */
  play(soundName: keyof typeof this.sounds): void {
    if (!this.enabled() || !this.audioContext) return;

    try {
      const soundFn = this.sounds[soundName];
      soundFn();
    } catch (error) {
      console.error('[Sound] Error playing sound:', soundName, error);
    }
  }

  /**
   * Perfect note sound - bright, uplifting chime
   */
  private createPerfectNoteSound(): void {
    if (!this.audioContext) return;

    const now = this.audioContext.currentTime;
    const osc = this.audioContext.createOscillator();
    const gain = this.audioContext.createGain();

    osc.connect(gain);
    gain.connect(this.audioContext.destination);

    // Bell-like tone
    osc.type = 'sine';
    osc.frequency.setValueAtTime(880, now); // A5
    osc.frequency.exponentialRampToValueAtTime(1760, now + 0.1); // A6

    // Quick fade out
    gain.gain.setValueAtTime(this.volume() * 0.3, now);
    gain.gain.exponentialRampToValueAtTime(0.01, now + 0.3);

    osc.start(now);
    osc.stop(now + 0.3);
  }

  /**
   * Good note sound - pleasant but subtle
   */
  private createGoodNoteSound(): void {
    if (!this.audioContext) return;

    const now = this.audioContext.currentTime;
    const osc = this.audioContext.createOscillator();
    const gain = this.audioContext.createGain();

    osc.connect(gain);
    gain.connect(this.audioContext.destination);

    osc.type = 'sine';
    osc.frequency.setValueAtTime(660, now); // E5

    gain.gain.setValueAtTime(this.volume() * 0.2, now);
    gain.gain.exponentialRampToValueAtTime(0.01, now + 0.2);

    osc.start(now);
    osc.stop(now + 0.2);
  }

  /**
   * Wrong note sound - very subtle soft thud
   */
  private createWrongNoteSound(): void {
    if (!this.audioContext) return;

    const now = this.audioContext.currentTime;
    const osc = this.audioContext.createOscillator();
    const gain = this.audioContext.createGain();
    const filter = this.audioContext.createBiquadFilter();

    osc.connect(filter);
    filter.connect(gain);
    gain.connect(this.audioContext.destination);

    // Low, muffled tone - not annoying
    osc.type = 'sine';
    osc.frequency.setValueAtTime(150, now);
    osc.frequency.exponentialRampToValueAtTime(80, now + 0.1);

    // Low pass filter to make it soft
    filter.type = 'lowpass';
    filter.frequency.value = 200;

    // Very quiet and short
    gain.gain.setValueAtTime(this.volume() * 0.08, now);
    gain.gain.exponentialRampToValueAtTime(0.001, now + 0.1);

    osc.start(now);
    osc.stop(now + 0.1);
  }

  /**
   * Level up sound - triumphant fanfare
   */
  private createLevelUpSound(): void {
    if (!this.audioContext) return;

    const now = this.audioContext.currentTime;

    // Three ascending notes
    const notes = [
      { freq: 523, time: 0 },      // C5
      { freq: 659, time: 0.1 },    // E5
      { freq: 784, time: 0.2 }     // G5
    ];

    notes.forEach(({ freq, time }) => {
      const osc = this.audioContext!.createOscillator();
      const gain = this.audioContext!.createGain();

      osc.connect(gain);
      gain.connect(this.audioContext!.destination);

      osc.type = 'triangle';
      osc.frequency.setValueAtTime(freq, now + time);

      gain.gain.setValueAtTime(this.volume() * 0.4, now + time);
      gain.gain.exponentialRampToValueAtTime(0.01, now + time + 0.3);

      osc.start(now + time);
      osc.stop(now + time + 0.3);
    });
  }

  /**
   * Achievement unlock sound - celebratory chord
   */
  private createAchievementSound(): void {
    if (!this.audioContext) return;

    const now = this.audioContext.currentTime;

    // Major chord
    const frequencies = [523, 659, 784]; // C-E-G

    frequencies.forEach(freq => {
      const osc = this.audioContext!.createOscillator();
      const gain = this.audioContext!.createGain();

      osc.connect(gain);
      gain.connect(this.audioContext!.destination);

      osc.type = 'sine';
      osc.frequency.setValueAtTime(freq, now);

      gain.gain.setValueAtTime(this.volume() * 0.3, now);
      gain.gain.exponentialRampToValueAtTime(0.01, now + 0.5);

      osc.start(now);
      osc.stop(now + 0.5);
    });
  }

  /**
   * Combo sound - gentle chime (softer than before)
   */
  private createComboSound(): void {
    if (!this.audioContext) return;

    const now = this.audioContext.currentTime;
    const osc = this.audioContext.createOscillator();
    const gain = this.audioContext.createGain();

    osc.connect(gain);
    gain.connect(this.audioContext.destination);

    // Gentle rising tone with soft sine wave
    osc.type = 'sine';
    osc.frequency.setValueAtTime(440, now);
    osc.frequency.exponentialRampToValueAtTime(660, now + 0.15);

    // Quieter and shorter
    gain.gain.setValueAtTime(this.volume() * 0.15, now);
    gain.gain.exponentialRampToValueAtTime(0.01, now + 0.2);

    osc.start(now);
    osc.stop(now + 0.2);
  }

  /**
   * Toggle sound on/off
   */
  toggleSound(): void {
    this.enabled.set(!this.enabled());
  }

  /**
   * Set volume (0-1)
   */
  setVolume(volume: number): void {
    this.volume.set(Math.max(0, Math.min(1, volume)));
  }

  /**
   * Check if sound is enabled
   */
  isEnabled(): boolean {
    return this.enabled();
  }

  /**
   * Get current volume
   */
  getVolume(): number {
    return this.volume();
  }
}

import { Injectable } from '@angular/core';

/**
 * Staff Renderer Service
 *
 * Централізована логіка малювання нотного стану (п'яти ліній).
 *
 * Нотний стан складається з 5 горизонтальних ліній та 4 проміжків між ними.
 * Кожна лінія та проміжок представляє ноту діатонічної гами.
 */
@Injectable({
  providedIn: 'root'
})
export class StaffRendererService {

  /**
   * Намалювати нотний стан (5 ліній)
   *
   * @param ctx - Canvas context
   * @param topY - Y координата верхньої лінії стану
   * @param lineSpacing - відстань між лініями
   * @param width - ширина ліній
   * @param startX - початкова X координата (за замовчуванням 0)
   * @param color - колір ліній
   * @param lineWidth - товщина ліній
   */
  drawStaff(
    ctx: CanvasRenderingContext2D,
    topY: number,
    lineSpacing: number,
    width: number,
    startX: number = 0,
    color: string = 'rgba(255, 255, 255, 0.6)',
    lineWidth: number = 1.5
  ): void {
    ctx.strokeStyle = color;
    ctx.lineWidth = lineWidth;

    // Намалювати 5 ліній
    for (let i = 0; i < 5; i++) {
      const y = topY + i * lineSpacing;
      ctx.beginPath();
      ctx.moveTo(startX, y);
      ctx.lineTo(startX + width, y);
      ctx.stroke();
    }
  }

  /**
   * Намалювати великий нотний стан (скрипковий та басовий разом)
   *
   * @param ctx - Canvas context
   * @param height - загальна висота canvas
   * @param width - ширина ліній
   * @param trebleTopPercent - верх скрипкового стану як відсоток висоти (за замовчуванням 0.1)
   * @param bassTopPercent - верх басового стану як відсоток висоти (за замовчуванням 0.55)
   * @param staffHeightPercent - висота кожного стану як відсоток загальної висоти (за замовчуванням 0.35)
   * @param color - колір ліній
   * @param lineWidth - товщина ліній
   */
  drawGrandStaff(
    ctx: CanvasRenderingContext2D,
    height: number,
    width: number,
    trebleTopPercent: number = 0.1,
    bassTopPercent: number = 0.55,
    staffHeightPercent: number = 0.35,
    color: string = 'rgba(255, 255, 255, 0.6)',
    lineWidth: number = 1.5
  ): void {
    const staffHeight = height * staffHeightPercent;
    const lineSpacing = staffHeight / 5;

    // Скрипковий стан (зверху)
    const trebleTop = height * trebleTopPercent;
    this.drawStaff(ctx, trebleTop, lineSpacing, width, 0, color, lineWidth);

    // Басовий стан (знизу)
    const bassTop = height * bassTopPercent;
    this.drawStaff(ctx, bassTop, lineSpacing, width, 0, color, lineWidth);
  }

  /**
   * Намалювати додаткові лінії (ledger lines) для нот поза станом
   *
   * @param ctx - Canvas context
   * @param x - X координата центру ноти
   * @param y - Y координата ноти
   * @param staffTop - верх нотного стану
   * @param staffBottom - низ нотного стану (staffTop + lineSpacing * 4)
   * @param lineSpacing - відстань між лініями
   * @param color - колір ліній
   * @param lineWidth - товщина ліній
   * @param ledgerWidth - ширина додаткової лінії (за замовчуванням 36px)
   */
  drawLedgerLines(
    ctx: CanvasRenderingContext2D,
    x: number,
    y: number,
    staffTop: number,
    staffBottom: number,
    lineSpacing: number,
    color: string = 'rgba(255, 255, 255, 0.7)',
    lineWidth: number = 1.5,
    ledgerWidth: number = 36
  ): void {
    ctx.strokeStyle = color;
    ctx.lineWidth = lineWidth;

    const halfLedger = ledgerWidth / 2;

    // Додаткові лінії вище стану
    if (y < staffTop) {
      for (let ly = staffTop - lineSpacing; ly >= y - lineSpacing / 2; ly -= lineSpacing) {
        // Малюємо лише якщо нота близька до лінії
        if (Math.abs(y - ly) < lineSpacing / 4) {
          ctx.beginPath();
          ctx.moveTo(x - halfLedger, ly);
          ctx.lineTo(x + halfLedger, ly);
          ctx.stroke();
        }
      }
    }

    // Додаткові лінії нижче стану
    if (y > staffBottom) {
      for (let ly = staffBottom + lineSpacing; ly <= y + lineSpacing / 2; ly += lineSpacing) {
        // Малюємо лише якщо нота близька до лінії
        if (Math.abs(y - ly) < lineSpacing / 4) {
          ctx.beginPath();
          ctx.moveTo(x - halfLedger, ly);
          ctx.lineTo(x + halfLedger, ly);
          ctx.stroke();
        }
      }
    }
  }

  /**
   * Розрахувати відстань між лініями на основі висоти стану
   */
  getLineSpacing(staffHeight: number): number {
    return staffHeight / 5;
  }

  /**
   * Отримати Y координату певної лінії стану
   * @param staffTop - верх нотного стану
   * @param lineSpacing - відстань між лініями
   * @param lineIndex - індекс лінії (0 = верхня, 4 = нижня)
   */
  getLineY(staffTop: number, lineSpacing: number, lineIndex: number): number {
    return staffTop + lineIndex * lineSpacing;
  }
}

import { Injectable } from '@angular/core';
import { invoke } from '@tauri-apps/api/core';
import { listen, UnlistenFn } from '@tauri-apps/api/event';

/**
 * Tauri IPC wrapper service
 * Handles all communication between Angular frontend and Rust backend
 */
@Injectable({
    providedIn: 'root'
})
export class TauriService {
    private listeners: Map<string, UnlistenFn> = new Map();

    /**
     * Invoke a Tauri command
     * @param cmd Command name (matches #[tauri::command] in Rust)
     * @param args Optional arguments
     */
    async invoke<T>(cmd: string, args?: Record<string, unknown>): Promise<T> {
        try {
            return await invoke<T>(cmd, args);
        } catch (error) {
            console.error(`[Tauri] Command "${cmd}" failed:`, error);
            throw error;
        }
    }

    /**
     * Listen to Tauri events from backend
     * @param event Event name
     * @param handler Callback function
     */
    async listen<T>(event: string, handler: (payload: T) => void): Promise<void> {
        // Clean up existing listener if any
        await this.unlisten(event);

        const unlisten = await listen<T>(event, (evt) => {
            handler(evt.payload);
        });

        this.listeners.set(event, unlisten);
    }

    /**
     * Stop listening to an event
     */
    async unlisten(event: string): Promise<void> {
        const unlisten = this.listeners.get(event);
        if (unlisten) {
            unlisten();
            this.listeners.delete(event);
        }
    }

    /**
     * Clean up all listeners (call in ngOnDestroy)
     */
    async cleanup(): Promise<void> {
        for (const unlisten of this.listeners.values()) {
            unlisten();
        }
        this.listeners.clear();
    }

    /**
     * Check if running in Tauri environment
     */
    isTauri(): boolean {
        return !!(window as any).__TAURI_INTERNALS__;
    }
}

import { Injectable } from '@angular/core';

/**
 * Time Signature Renderer Service
 *
 * Централізована логіка малювання тактового розміру (метра).
 *
 * Тактовий розмір показує кількість долей в такті та їх тривалість.
 * Наприклад: 4/4 означає 4 чвертні ноти в такті, 3/4 - 3 чвертні, 6/8 - 6 восьмих.
 *
 * Позиція: після ключа та ключових знаків на початку твору.
 */
@Injectable({
  providedIn: 'root'
})
export class TimeSignatureRendererService {

  /**
   * Намалювати тактовий розмір
   *
   * @param ctx - Canvas context
   * @param x - X координата центру тактового розміру
   * @param staffTop - Y координата верхньої лінії нотного стану
   * @param lineSpacing - відстань між лініями
   * @param numerator - чисельник (кількість долей)
   * @param denominator - знаменник (тривалість долі: 4=чверть, 8=восьма, 2=половинна)
   * @param color - колір тексту
   */
  drawTimeSignature(
    ctx: CanvasRenderingContext2D,
    x: number,
    staffTop: number,
    lineSpacing: number,
    numerator: number,
    denominator: number,
    color: string = '#ffffff'
  ): void {
    const fontSize = lineSpacing * 1.8;
    const staffMiddle = staffTop + lineSpacing * 2; // Середня лінія

    ctx.save();
    ctx.fillStyle = color;
    ctx.font = `bold ${fontSize}px Arial, sans-serif`;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';

    // Чисельник (верхнє число) - над серединою стану
    const numeratorY = staffMiddle - lineSpacing * 0.8;
    ctx.fillText(numerator.toString(), x, numeratorY);

    // Знаменник (нижнє число) - під серединою стану
    const denominatorY = staffMiddle + lineSpacing * 0.8;
    ctx.fillText(denominator.toString(), x, denominatorY);

    ctx.restore();
  }

  /**
   * Намалювати спеціальні тактові розміри (C та ¢)
   *
   * @param ctx - Canvas context
   * @param x - X координата центру
   * @param staffTop - Y координата верхньої лінії
   * @param lineSpacing - відстань між лініями
   * @param type - тип: 'common' (C для 4/4) або 'cut' (¢ для 2/2)
   * @param color - колір символу
   */
  drawCommonTime(
    ctx: CanvasRenderingContext2D,
    x: number,
    staffTop: number,
    lineSpacing: number,
    type: 'common' | 'cut' = 'common',
    color: string = '#ffffff'
  ): void {
    const fontSize = lineSpacing * 3;
    const staffMiddle = staffTop + lineSpacing * 2;

    ctx.save();
    ctx.fillStyle = color;
    ctx.font = `bold ${fontSize}px Arial, sans-serif`;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';

    // C для 4/4 (common time) або ¢ для 2/2 (cut time, alla breve)
    const symbol = type === 'common' ? 'C' : 'ℂ';
    ctx.fillText(symbol, x, staffMiddle);

    ctx.restore();
  }

  /**
   * Розрахувати ширину тактового розміру для правильного розміщення наступних елементів
   */
  getWidth(numerator: number, denominator: number, lineSpacing: number): number {
    // Приблизна ширина на основі розміру шрифту
    const fontSize = lineSpacing * 1.8;
    const maxDigits = Math.max(
      numerator.toString().length,
      denominator.toString().length
    );
    return fontSize * 0.6 * maxDigits + lineSpacing * 0.5;
  }

  /**
   * Перевірити чи є тактовий розмір валідним
   */
  isValidTimeSignature(numerator: number, denominator: number): boolean {
    // Чисельник повинен бути > 0
    if (numerator <= 0) return false;

    // Знаменник повинен бути степенем 2 (1, 2, 4, 8, 16, 32, ...)
    if (denominator <= 0) return false;
    if ((denominator & (denominator - 1)) !== 0) return false;

    return true;
  }

  /**
   * Отримати кількість долей в такті (в чвертних нотах)
   */
  getBeatsPerMeasure(numerator: number, denominator: number): number {
    // Конвертувати в чвертні ноти
    // 4/4 = 4 чверті, 3/4 = 3 чверті, 6/8 = 3 чверті (6 * 1/8 / 1/4 = 6/8 * 4 = 3)
    return numerator * (4 / denominator);
  }

  /**
   * Отримати назву тактового розміру
   */
  getTimeSignatureName(numerator: number, denominator: number): string {
    if (numerator === 4 && denominator === 4) return 'Common Time (4/4)';
    if (numerator === 2 && denominator === 2) return 'Cut Time (2/2)';
    if (numerator === 3 && denominator === 4) return 'Waltz Time (3/4)';
    if (numerator === 6 && denominator === 8) return 'Compound Duple (6/8)';
    return `${numerator}/${denominator}`;
  }
}

