    }

    .breakdown-item.error {
      background: #ffebee;
      color: #c62828;
    }

    .tips-section {
      display: flex;
      align-items: center;
      gap: 0.5rem;
      padding: 0.75rem 1rem;
      background: #e3f2fd;
      border-radius: 8px;
      margin-bottom: 1.5rem;
      color: #1565c0;
      font-size: 0.9rem;
      text-align: left;
    }

    .tips-section mat-icon {
      color: #ffc107;
      flex-shrink: 0;
