  grid-template-columns: repeat(2, 1fr);
  gap: 1rem;
  margin-bottom: 2rem;
}

.stat-card {
  background: #f5f5f5;
  padding: 1.5rem;
  border-radius: 12px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.5rem;
  transition: transform 0.2s;
}

.stat-card:hover {
  transform: translateY(-2px);
}

.stat-card mat-icon {
  font-size: 32px;
  width: 32px;
  height: 32px;
  color: #3f51b5;
}

.stat-card.excellent mat-icon {
  color: #4caf50;
}

.stat-card.fire mat-icon {
  color: #ff9800;
  animation: pulse 1s infinite;
}

@keyframes pulse {
  0%, 100% { transform: scale(1); }
  50% { transform: scale(1.1); }
}

.stat-value {
  font-size: 2rem;
  font-weight: 700;
  color: #333;
}

.stat-label {
  font-size: 0.9rem;
  color: #666;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.stat-detail {
  font-size: 0.8rem;
  color: #888;
  margin-top: 0.25rem;
}

.performance-message {
  margin-bottom: 2rem;
  padding: 1rem;
  border-radius: 8px;
}

.performance-message p {
  margin: 0;
  font-size: 1.2rem;
  font-weight: 500;
}

.excellent { color: #4caf50; }
.good { color: #2196f3; }
.okay { color: #ff9800; }
.needs-work { color: #f44336; }

.breakdown-section {
  margin-bottom: 1.5rem;
  padding: 1rem;
  background: #fafafa;
  border-radius: 8px;
}

.breakdown-section h3 {
  margin: 0 0 1rem 0;
  font-size: 0.9rem;
  color: #666;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.breakdown-grid {
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem;
  justify-content: center;
}

.breakdown-item {
  display: flex;
  align-items: center;
  gap: 0.25rem;
  padding: 0.5rem 0.75rem;
  border-radius: 20px;
  font-size: 0.85rem;
}

.breakdown-item mat-icon {
  font-size: 18px;
  width: 18px;
  height: 18px;
}

.breakdown-item .count {
  font-weight: 700;
}

.breakdown-item .label {
  color: inherit;
  opacity: 0.9;
}

.breakdown-item.success {
  background: #e8f5e9;
  color: #2e7d32;
}

.breakdown-item.warning {
  background: #fff3e0;
  color: #ef6c00;
}

.breakdown-item.error {
  background: #ffebee;
  color: #c62828;
}

.tips-section {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.75rem 1rem;
  background: #e3f2fd;
  border-radius: 8px;
  margin-bottom: 1.5rem;
  color: #1565c0;
  font-size: 0.9rem;
  text-align: left;
}

.tips-section mat-icon {
  color: #ffc107;
  flex-shrink: 0;
}

.actions {
  display: flex;
  gap: 1rem;
  justify-content: center;
}

.actions button {
  min-width: 150px;
}

