    }

    .tonic-dot {
        position: absolute;
        top: 18px;
        width: 6px;
        height: 6px;
        background: #8B5CF6;
        border-radius: 50%;
        box-shadow: 0 1px 3px rgba(139, 92, 246, 0.5);
        pointer-events: none;
    }
